import { useState, useRef, useEffect } from 'react';

function ExerciseCard({ exercise, dayOfWeek, days, onEdit, onDelete, onCopyExercise, onDragStart, onDragEnd, errors = {} }) {
    const [showCopyMenu, setShowCopyMenu] = useState(false);
    const menuRef = useRef(null);
    const hasError = !!Object.keys(errors).length;

    useEffect(() => {
        if (!showCopyMenu) return;
        const handleClick = (e) => {
            if (menuRef.current && !menuRef.current.contains(e.target)) {
                setShowCopyMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClick);
        return () => document.removeEventListener('mousedown', handleClick);
    }, [showCopyMenu]);

    const destinations = days.filter((d) => d.dayOfWeek !== dayOfWeek);

    return (
        <div
            className={`builder-card${hasError ? ' builder-card--error' : ''}`}
            draggable
            onDragStart={() => onDragStart(exercise, dayOfWeek)}
            onDragEnd={onDragEnd}
        >
            <div className="builder-card__drag">
                <i className="fa-solid fa-grip-vertical"></i>
            </div>
            <div className="builder-card__body">
                <div className="builder-card__name">{exercise.exercise.name}</div>
                <div className="builder-card__params">
                    <span className="builder-card__param">
                        <i className="fa-solid fa-rotate-left"></i>
                        {exercise.sets} × {exercise.reps}
                    </span>
                    <span>·</span>
                    <span className="builder-card__param">
                        <i className="fa-regular fa-clock"></i>
                        {exercise.rest}s
                    </span>
                    {exercise.load && (
                        <>
                            <span>·</span>
                            <span>{exercise.load}</span>
                        </>
                    )}
                </div>
            </div>
            <div className="builder-card__actions">
                <div className="position-relative" ref={menuRef}>
                    <button
                        className="btn-icon"
                        title="Copia in un altro giorno"
                        onClick={() => setShowCopyMenu((v) => !v)}
                    >
                        <i className="fa-solid fa-copy"></i>
                    </button>
                    {showCopyMenu && (
                        <div className="context-menu">
                            <div className="context-menu__header">
                                <span>Copia in…</span>
                                <button className="context-menu__close" onClick={() => setShowCopyMenu(false)}>
                                    <i className="fa-solid fa-xmark"></i>
                                </button>
                            </div>
                            {destinations.map((dest) => (
                                <button
                                    key={dest.dayOfWeek}
                                    className="context-menu__item"
                                    onClick={() => { onCopyExercise(exercise, dest.dayOfWeek); setShowCopyMenu(false); }}
                                >
                                    <span className="context-menu__num">G{days.indexOf(dest) + 1}</span>
                                    {dest.name}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
                <button
                    className="btn-icon"
                    onClick={() => onEdit(exercise)}
                    title="Modifica"
                >
                    <i className="fa-solid fa-pen"></i>
                </button>
                <button
                    className="btn-icon btn-icon--danger"
                    onClick={() => onDelete(exercise.id)}
                    title="Elimina"
                >
                    <i className="fa-solid fa-trash"></i>
                </button>
            </div>
        </div>
    );
}

export default ExerciseCard;
