import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Alert } from 'react-bootstrap';
import { useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import BaseLayout from '../../components/BaseLayout';
import CoachSchedaHeader from '../../components/CoachSchedaHeader';
import { AthletesService } from '../../services/athletes.service';
import { hideLoader, showLoader } from '../../features/loader/loaderSlice';

// ---- Helper functions ----

const getMuscleGroups = (exercises) => {
    const groups = exercises.map((e) => e.gruppoMuscolare).filter(Boolean);
    return [...new Set(groups)].join(', ') || 'Gruppi muscolari non specificati';
};

const getTotalSets = (exercises) =>
    exercises.reduce((sum, ex) => sum + (Number(ex.serieTotali) || 0), 0);

const estimateDuration = (exercises) => {
    const seconds = exercises.reduce((sum, ex) => {
        const sets = Number(ex.serieTotali) || 0;
        const rest = Number(ex.recuperoXserie) || 60;
        return sum + sets * (rest + 45);
    }, 0);
    const minutes = Math.round(seconds / 60 / 5) * 5;
    return Math.max(minutes, 5);
};

// ---- Page component ----

const AthleteWorkoutDetail = () => {
    const { userId, schedaId } = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();

    const [workout, setWorkout] = useState(null);
    const [athlete, setAthlete] = useState(null);
    const [error, setError] = useState(null);

    useEffect(() => {
        const load = async () => {
            dispatch(showLoader());
            setError(null);
            try {
                const [workoutRes, athleteRes] = await Promise.all([
                    AthletesService.getAthleteWorkout(userId, schedaId),
                    AthletesService.getAthlete(userId),
                ]);
                setWorkout(workoutRes.data?.data ?? workoutRes.data ?? null);
                setAthlete(athleteRes.data?.data ?? athleteRes.data ?? null);
            } catch (err) {
                setError(err.response?.data?.message || 'Errore nel caricamento della scheda');
            } finally {
                dispatch(hideLoader());
            }
        };
        load();
    }, [userId, schedaId]);

    const handleDelete = async () => {
        if (!window.confirm('Sei sicuro di voler eliminare questa scheda?')) return;
        dispatch(showLoader());
        try {
            const { data } = await AthletesService.deleteAthleteWorkout(userId, schedaId);
            toast.success(data?.message || 'Scheda eliminata con successo');
            navigate(`/coach/athletes/${userId}`);
        } catch (err) {
            toast.error(err.response?.data?.message || "Errore durante l'eliminazione della scheda");
            dispatch(hideLoader());
        }
    };

    const athleteName = athlete
        ? [athlete.nome, athlete.cognome].filter(Boolean).join(' ') || athlete.username || null
        : null;

    return (
        <BaseLayout>
            <div className="page-content">
                {error && (
                    <Alert variant="danger" dismissible onClose={() => setError(null)}>
                        {error}
                    </Alert>
                )}

                {workout && (
                    <>
                        {/* Breadcrumb */}
                        <nav className="awd-breadcrumb">
                            <button onClick={() => navigate('/coach/athletes')}>
                                I miei Atleti
                            </button>
                            <i className="fas fa-chevron-right" />
                            <button onClick={() => navigate(`/coach/athletes/${userId}`)}>
                                {athleteName ?? '...'}
                            </button>
                            <i className="fas fa-chevron-right" />
                            <span>{workout.nomeScheda}</span>
                        </nav>

                        {/* Header */}
                        <CoachSchedaHeader
                            workout={workout}
                            onBack={() => navigate(`/coach/athletes/${userId}`)}
                            onDelete={handleDelete}
                        />

                        {/* Giorni */}
                        <section className="awd-days">
                            {Object.entries(workout.esercizi_x_day || {}).map(([day, exercises]) => (
                                <div className="awd-day-card" key={day}>
                                    <div className="awd-day-card__header">
                                        <div className="awd-day-card__header-left">
                                            <div className="awd-day-number">{day}</div>
                                            <div className="awd-day-info">
                                                <h3 className="awd-day-info__muscles">
                                                    {getMuscleGroups(exercises)}
                                                </h3>
                                                <div className="awd-day-info__meta">
                                                    <span>
                                                        <i className="fas fa-dumbbell" />
                                                        {exercises.length}{' '}
                                                        {exercises.length === 1 ? 'esercizio' : 'esercizi'}
                                                    </span>
                                                    <span>
                                                        <i className="fas fa-layer-group" />
                                                        {getTotalSets(exercises)} serie
                                                    </span>
                                                    <span>
                                                        <i className="fas fa-clock" />
                                                        ~{estimateDuration(exercises)} min
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="awd-exercise-list">
                                        {exercises.length === 0 ? (
                                            <div className="awd-empty-exercises">
                                                <i className="fas fa-dumbbell" />
                                                <p>Nessun esercizio in questo giorno</p>
                                            </div>
                                        ) : (
                                            exercises.map((ex, i) => (
                                                <div className="awd-exercise-row" key={i}>
                                                    <div className="awd-exercise-row__body">
                                                        <span className="awd-exercise-row__name">
                                                            {ex.nome}
                                                        </span>
                                                        <div className="awd-exercise-row__specs">
                                                            {ex.serieTotali && (
                                                                <span className="awd-spec-chip">
                                                                    <strong>{ex.serieTotali}</strong> serie
                                                                </span>
                                                            )}
                                                            {(ex.ripetizioni || ex.numeroRipetizioni) && (
                                                                <span className="awd-spec-chip">
                                                                    <strong>{ex.ripetizioni || ex.numeroRipetizioni}</strong> rip
                                                                </span>
                                                            )}
                                                            {ex.recuperoXserie && (
                                                                <span className="awd-spec-chip">
                                                                    <strong>{ex.recuperoXserie}"</strong> rec
                                                                </span>
                                                            )}
                                                            {ex.noteEsercizio && (
                                                                <span
                                                                    className="awd-spec-chip awd-spec-chip--note"
                                                                    title={ex.noteEsercizio}
                                                                >
                                                                    <i className="fas fa-note-sticky" /> nota
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>
                                            ))
                                        )}
                                    </div>
                                </div>
                            ))}

                            {Object.keys(workout.esercizi_x_day || {}).length === 0 && (
                                <div className="awd-empty-days">
                                    <i className="fas fa-calendar-plus" />
                                    <p>Nessun giorno configurato per questa scheda</p>
                                </div>
                            )}
                        </section>
                    </>
                )}
            </div>
        </BaseLayout>
    );
};

export default AthleteWorkoutDetail;
