import { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import {
    selectCurrentStep,
    selectMetadata,
    selectDays,
    selectWorkoutOptions,
    fetchWorkoutOptions,
    resetBuilder,
    setStep,
} from '../../features/workoutBuilder/workoutBuilderSlice';
import { SchedaService } from '../../services/scheda.service';
import WizardNavigation from './WizardNavigation';
import StepMetadata from './StepMetadata';
import StepExercises from './StepExercises';
import StepSummary from './StepSummary';
import { toast } from 'react-toastify';
import { parseErrors, serializeWorkoutPayload, serializeTemplatePayload } from '../../utils/workoutBuilderHelpers';
import { WorkoutTemplatesService } from '../../services/workoutTemplates.service';
import { AthletesService } from '../../services/athletes.service';
import { useAuth } from '../../hooks/useAuth';

const STEPS = [StepMetadata, StepExercises, StepSummary];

function WizardContainer({ onCancel }) {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const currentStep = useSelector(selectCurrentStep);
    const metadata = useSelector(selectMetadata);
    const days = useSelector(selectDays);
    const { loaded: optionsLoaded } = useSelector(selectWorkoutOptions);
    const { isAdmin, isCoach } = useAuth();

    const [saving, setSaving] = useState(false);
    const [fieldErrors, setFieldErrors] = useState({});
    const [daysErrors, setDaysErrors] = useState({});
    const [athletes, setAthletes] = useState([]);

    useEffect(() => {
        if (!optionsLoaded) dispatch(fetchWorkoutOptions());
    }, [optionsLoaded, dispatch]);

    useEffect(() => {
        if (isAdmin || isCoach) {
            AthletesService.getAthletes()
                .then(({ data }) => setAthletes(data.data))
                .catch(() => { });
        }
    }, [isAdmin, isCoach]);

    const isLastStep = currentStep === STEPS.length - 1;

    const metadataValid =
        metadata.title.trim() !== '' &&
        metadata.level !== '' &&
        metadata.type !== '' &&
        (metadata.isTemplate || (metadata.objective !== '' && metadata.expiry !== ''));

    const hasAtLeastOneExercise = days.some((d) => d.exercises.length > 0);

    const canProceed =
        (currentStep !== 0 || metadataValid) &&
        (currentStep !== 1 || hasAtLeastOneExercise);

    const handleFinish = async () => {
        setSaving(true);
        setFieldErrors({});
        setDaysErrors({});
        try {
            let result;
            if (metadata.isTemplate) {
                ({ data: result } = await WorkoutTemplatesService.createTemplate(serializeTemplatePayload(metadata, days)));
                dispatch(resetBuilder());
                toast.success(result.message);
            } else {
                ({ data: result } = await SchedaService.createSchedaV2(serializeWorkoutPayload(metadata, days)));
                dispatch(resetBuilder());
                toast.success(result.message, {
                    onClose: () => navigate(`/workouts/${result.data.idScheda}`),
                    onClick: () => navigate(`/workouts/${result.data.idScheda}`),
                });
            }
        } catch (err) {
            const responseData = err.response?.data;
            toast.error(responseData?.message ?? 'Errore durante il salvataggio. Riprova.');

            // Errori sul form...
            if (responseData?.errors) {
                const { general, days } = parseErrors(responseData.errors);
                setFieldErrors(general);
                setDaysErrors(days);
                if (!!Object.keys(general).length && !general.assigned_user_id) {
                    dispatch(setStep(0));
                } else if (!!Object.keys(days).length) {
                    dispatch(setStep(1));
                }
            }
        } finally {
            setSaving(false);
        }
    };

    const handleCancel = () => {
        const isDirty = metadata.title.trim() !== '' || days.some((d) => d.exercises.length > 0);
        if (isDirty && !window.confirm('Sei sicuro di voler annullare? Perderai tutti i progressi del programma.')) return;
        dispatch(resetBuilder());
        onCancel?.();
    };

    const StepComponent = STEPS[currentStep];

    return (
        <div className="wizard-container page-content">
            <WizardNavigation
                onCancel={handleCancel}
                canProceed={canProceed}
                isLastStep={isLastStep}
                onFinish={handleFinish}
                saving={saving}
            />

            <div className="wizard-body">
                <StepComponent fieldErrors={fieldErrors} daysErrors={daysErrors} athletes={athletes} />
            </div>
        </div>
    );
}

export default WizardContainer;
