import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { ExercisesService } from '../../services/exercises.service';
import { FavoriteExercisesService } from '../../services/favoriteExercises.service';
import { CustomExercisesService } from '../../services/customExercises.service';
import { hideLoader, showLoader } from '../loader/loaderSlice';

// Numero di esercizi per pagina in ogni chiamata al backend
const PER_PAGE = 20;

// Mappa le chiavi interne delle liste al servizio API corrispondente.
// Usata dal thunk per scegliere dinamicamente quale endpoint chiamare.
export const LIST_TIPES = {
    all: {
        label: 'Tutti',
        apiService: ExercisesService,
    },
    favorites: {
        label: 'Preferiti',
        apiService: FavoriteExercisesService,
    },
    custom: {
        label: 'Personali',
        apiService: CustomExercisesService,
    },
}

// Struttura iniziale di una singola lista paginata.
// `query` tiene traccia dell'ultima query per cui i dati sono stati caricati
// (null = mai fetchata); `pendingQuery` serve da guard contro risposte stale.
const makeList = () => ({
    items: [],
    page: 0,
    hasMore: true,
    loading: false,
    query: null,        // query dei dati attualmente in lista; null = mai fetchata
    pendingQuery: null, // query della richiesta in volo (guard anti-stale)
});

const initialState = {
    lists: {
        all: makeList(),
        favorites: makeList(),
        custom: makeList(),
    },
    activeTab: 'all',
    search: '',
};

// ─── Thunks ───────────────────────────────────────────────────────────────────

// Carica una pagina di esercizi per la lista indicata da `listKey`.
// Sceglie il servizio API dalla mappa LIST_TIPES, così non serve un if/else per tab.
export const fetchListPage = createAsyncThunk(
    'exercises/fetchListPage',
    async ({ listKey, page, query }) => {
        const params = { page, per_page: PER_PAGE, sort: 'name', direction: 'asc', search: query || undefined };

        /* let res;
        if (listKey === 'all')       res = (await ExercisesService.getAll(params)).data;
        else if (listKey === 'favorites') res = (await FavoriteExercisesService.getAll(params)).data;
        else                         res = (await CustomExercisesService.getAll(params)).data; */

        let { data } = await LIST_TIPES[listKey].apiService.getAll(params);

        return {
            listKey,
            page,
            query,
            items: data?.data ?? [],          // array di esercizi della pagina
            total: data?.meta?.total ?? 0,    // totale record per calcolare hasMore
        };
    }
);

// Aggiunge/rimuove un esercizio dai preferiti con aggiornamento ottimistico:
// la UI cambia subito (pending), si ripristina in caso di errore (rejected).
export const toggleFavoriteExercise = createAsyncThunk(
    'exercises/toggleFavorite',
    async (id, { dispatch, rejectWithValue }) => {
        try {
            dispatch(showLoader()); // Mostra il loader all'inizio
            const { data } = await FavoriteExercisesService.toggle(id);
            return data?.data?.exercise ?? {};
        } catch (error) {
            return rejectWithValue(error.response.data);
        } finally {
            dispatch(hideLoader());
        }
    }
);

// ─── Slice ────────────────────────────────────────────────────────────────────

const exercisesSlice = createSlice({
    name: 'exercises',
    initialState,
    reducers: {
        // Cambia la tab attiva e azzera la ricerca, così la nuova tab parte sempre pulita
        setActiveTab(state, { payload: tab }) {
            state.activeTab = tab;
            state.search = '';
        },
        // Aggiorna la stringa di ricerca grezza (il debounce avviene nell'hook UI)
        setSearch(state, { payload }) {
            state.search = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            // ── fetchListPage ──────────────────────────────────────────────────────
            .addCase(fetchListPage.pending, (state, action) => {
                const { listKey, query } = action.meta.arg;
                state.lists[listKey].loading = true;
                // Salva la query della richiesta in volo: se arriva una risposta con
                // una query diversa (stale), verrà scartata nel caso fulfilled.
                state.lists[listKey].pendingQuery = query;
            })
            .addCase(fetchListPage.fulfilled, (state, action) => {
                const { listKey, page, query, items, total } = action.payload;
                const list = state.lists[listKey];
                // Guard anti-stale: se nel frattempo è partita una query più recente,
                // questa risposta è ormai obsoleta e va ignorata.
                if (query !== list.pendingQuery) return;
                list.loading = false;
                list.query = query;
                list.page = page;
                // Pagina 1 → reset della lista; pagine successive → append
                list.items = page === 1 ? items : [...list.items, ...items];
                // hasMore è true finché i record caricati sono meno del totale
                list.hasMore = page * PER_PAGE < total;
            })
            .addCase(fetchListPage.rejected, (state, action) => {
                const { listKey } = action.meta.arg;
                const list = state.lists[listKey];
                list.loading = false;
                // In caso di errore blocca l'infinite scroll per evitare loop di retry
                list.hasMore = false;
            })

            // ── toggleFavorite ─────────────────────────────────────────────────────
            .addCase(toggleFavoriteExercise.fulfilled, (state, action) => {
                const ex = action.payload;

                // Nell'array "all" effettuo il toggle su is_favorite sull'esercizio interessato.
                const item = state.lists.all.items.find((i) => i.id === ex.id);
                if (item) item.is_favorite = ex.is_favorite;

                // Nella lista "favorites" se ex è diventato favorito lo aggiungo in cima, altrimenti lo rimuovo.
                state.lists.favorites.items = state.lists.favorites.items.filter((i) => i.id !== ex.id);
                if (ex.is_favorite) {
                    state.lists.favorites.items.unshift(ex);
                }
            });
    },
});

export const { setActiveTab, setSearch } = exercisesSlice.actions;
export default exercisesSlice.reducer;

// ─── Selectors ────────────────────────────────────────────────────────────────

export const selectActiveTab = (state) => state.exercises.activeTab;
export const selectSearch = (state) => state.exercises.search;
export const selectList = (listKey) => (state) => state.exercises.lists[listKey];
