import React, { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import BaseLayout from '../components/BaseLayout';
import UserProfileCard from '../components/UserProfileCard';
import SessionsCard from '../components/SessionsCard';
import { ProfileService } from '../services/profile.service';
import { hideLoader, showLoader } from '../features/loader/loaderSlice';
import { updateUser, fetchProfile, updateAvatar } from '../features/user/userSlice';
import { useValidationSystem } from '../hooks/useValidationSystem';

const Profilo = () => {
    const dispatch = useDispatch();
    const { user, errors: userErrors } = useSelector((state) => state.user);
    const { loading } = useSelector((state) => state.loader);
    const [isEditing, setIsEditing] = useState(false);
    const [avatarPreview, setAvatarPreview] = useState(null);

    const initState = {
        username: '', email: '', nome: '', cognome: '',
        cellulare: '', data_nascita: '', sesso: '',
    };

    const validations = [
        { name: 'username', required: true, min: 3, max: 50 },
        { name: 'email', required: true, extra: 'email' },
        { name: 'nome', required: false, max: 50 },
        { name: 'cognome', required: false, max: 50 },
        { name: 'cellulare', required: false, extra: 'phone' },
        { name: 'data_nascita', required: false },
        { name: 'sesso', required: false },
    ];

    const [data, dataToSend, setData, errors, setErrors, validate] = useValidationSystem({ initState, validations });

    const resetDefaultValuesUser = (userData) => {
        setData({
            username: userData.username,
            email: userData.email,
            nome: userData.nome || '',
            cognome: userData.cognome || '',
            cellulare: userData.cellulare || '',
            data_nascita: userData.data_nascita || '',
            sesso: userData.sesso || '',
        });
    };

    useEffect(() => {
        resetDefaultValuesUser(user);
        if (user.avatar_url) setAvatarPreview(user.avatar_url);
    }, [user, setData]);

    useEffect(() => {
        if (userErrors?.errors) {
            setErrors(userErrors.errors);
            if (userErrors.message) toast.error(userErrors.message);
        }
    }, [userErrors, setErrors]);

    useEffect(() => {
        document.title = 'Il mio Profilo';
    }, []);

    const handleInputChange = (e) => {
        e.preventDefault();
        const { name, value } = e.target;
        setData((prev) => ({ ...prev, [name]: value }));
    };

    const handleAvatarChange = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        if (!file.type.startsWith('image/')) { toast.error("Il file deve essere un'immagine"); return; }
        if (file.size > 10 * 1024 * 1024) { toast.error("L'immagine non deve superare i 10MB"); return; }

        const reader = new FileReader();
        reader.onloadend = () => setAvatarPreview(reader.result);
        reader.readAsDataURL(file);

        dispatch(showLoader());
        try {
            const { data } = await ProfileService.updateAvatar(file);
            toast.success(data.message);
            ProfileService.setUser(data.data);
            if (data.data.avatar_url) {
                setAvatarPreview(data.data.avatar_url);
                dispatch(updateAvatar(data.data.avatar_url));
            }
        } catch (error) {
            toast.error(error.response?.data?.message || "Errore nell'aggiornamento dell'avatar");
        } finally {
            dispatch(hideLoader());
        }
    };

    const handleSaveProfile = async (e) => {
        e.preventDefault();
        if (!validate()) return;
        const resultAction = await dispatch(updateUser(dataToSend));
        if (updateUser.fulfilled.match(resultAction)) {
            setIsEditing(false);
            const { data, message } = resultAction.payload;
            toast.success(message);
            ProfileService.setUser(data);
        }
    };

    const handleCancelEdit = () => {
        resetDefaultValuesUser(user);
        setIsEditing(false);
        setErrors({});
    };

    const handleReloadProfile = async () => {
        const resultAction = await dispatch(fetchProfile());
        if (fetchProfile.fulfilled.match(resultAction)) {
            toast.success(resultAction.payload.message || 'Profilo ricaricato con successo');
        } else {
            toast.error('Errore nel ricaricamento del profilo');
        }
    };

    return (
        <BaseLayout>
            <div className="page-content">
                <div className="page-header">
                    <h1 className="page-header__title">Il mio Profilo</h1>
                    <p className="page-header__subtitle">Gestisci le tue informazioni personali e le sessioni attive</p>
                </div>

                <UserProfileCard
                    user={data}
                    isEditing={isEditing}
                    avatarPreview={avatarPreview}
                    onAvatarChange={handleAvatarChange}
                    onReload={handleReloadProfile}
                    onEdit={() => setIsEditing(true)}
                    onSave={handleSaveProfile}
                    onCancelEdit={handleCancelEdit}
                    onInputChange={handleInputChange}
                    errors={errors}
                    loading={loading}
                />

                <SessionsCard />
            </div>
        </BaseLayout>
    );
};

export default Profilo;
