import React, { useMemo, useState } from 'react';
import { Alert, Badge, Button, Card } from 'react-bootstrap';
import useDataTable from '../../hooks/useDataTable';
import DataTable from '../../components/Datatable/DataTable';
import FiltersDropdown from '../../components/FiltersDropdown';
import { SearchInput } from '../../components/FormComponents';
import PageHeader from '../../components/PageHeader';
import ActionsDropdown from '../../components/ActionsDropdown';
import { WorkoutTemplatesService } from '../../services/workoutTemplates.service';

function WorkoutTemplateList({ onNewProgram, onSelectTemplate }) {
    const {
        data: templates,
        loading,
        error,
        totalItems,
        page,
        pageSize,
        totalPages,
        startItem,
        endItem,
        pageSizeOptions,
        setPage,
        setPageSize,
        goToNextPage,
        goToPrevPage,
        sortField,
        sortOrder,
        toggleSort,
        search,
        customFilters,
        applyFilters,
    } = useDataTable({
        fetchFn: (params) => WorkoutTemplatesService.getAll(params),
        defaultPageSize: 15,
        defaultSortField: 'name',
        defaultSortOrder: 'asc',
        pageSizeOptions: [15, 25, 50],
    });

    const [searchInput, setSearchInput] = useState(search ?? '');

    const activeCount = useMemo(() => {
        let count = Object.keys(customFilters).length;
        if (search) count++;
        return count;
    }, [customFilters, search]);

    const handleFilterSubmit = () => {
        applyFilters({ search: searchInput, set: {}, remove: [] });
    };

    const handleFilterReset = () => {
        setSearchInput('');
        applyFilters({ search: '', set: {}, remove: [] });
    };

    const columns = [
        {
            key: 'name',
            label: 'Template',
            sortable: false,
            render: (item) => (
                <div className="d-flex align-items-center gap-2">
                    <span className="fw-medium">{item.name}</span>
                    {item.is_global && <span className="tag-pill">Globale</span>}
                </div>
            ),
        },
        {
            key: 'description',
            label: 'Descrizione',
            sortable: false,
            render: (item) => (
                <span className="text-muted small">{item.description || '—'}</span>
            ),
        },
        {
            key: 'weekly_sessions',
            label: 'Sessioni/sett.',
            sortable: false,
            render: (item) => <Badge bg="primary">{item.weekly_sessions}x</Badge>,
        },
        {
            key: 'exercises_count',
            label: 'Esercizi',
            sortable: false,
            render: (item) => item.exercises_count,
        },
    ];

    return (
        <div className="page-content">
            <PageHeader
                title="Builder Workout"
                subtitle="Scegli un template esistente oppure crea un nuovo programma da zero"
                actions={[
                    <Button key="create" variant="primary" onClick={onNewProgram}>
                        <i className="fa-solid fa-plus me-2"></i>
                        Nuovo Programma
                    </Button>,
                ]}
            />

            {error && (
                <Alert variant="danger" dismissible>
                    Errore nel caricamento dei template: {error}
                </Alert>
            )}

            <FiltersDropdown
                activeCount={activeCount}
                onSubmit={handleFilterSubmit}
                onReset={handleFilterReset}
            >
                <div className="filter-item">
                    <SearchInput
                        name="search"
                        placeholder="Cerca per nome..."
                        value={searchInput}
                        onInput={(e) => setSearchInput(e.target.value)}
                    />
                </div>
            </FiltersDropdown>

            <Card className="datatable-card">
                <Card.Body>
                    <DataTable
                        columns={columns}
                        data={templates}
                        loading={loading}
                        emptyMessage="Nessun template trovato"
                        itemLabel="template"
                        tableClassName="programs-table"
                        showActions
                        renderActions={(template) => (
                            <ActionsDropdown items={[
                                {
                                    label: 'Usa template',
                                    icon: 'fa-solid fa-arrow-right',
                                    onClick: () => onSelectTemplate(template),
                                },
                            ]} />
                        )}
                        sortField={sortField}
                        sortOrder={sortOrder}
                        toggleSort={toggleSort}
                        startItem={startItem}
                        endItem={endItem}
                        totalItems={totalItems}
                        pageSize={pageSize}
                        setPageSize={setPageSize}
                        pageSizeOptions={pageSizeOptions}
                        page={page}
                        totalPages={totalPages}
                        setPage={setPage}
                        goToPrevPage={goToPrevPage}
                        goToNextPage={goToNextPage}
                    />
                </Card.Body>
            </Card>
        </div>
    );
}

export default WorkoutTemplateList;
