import ExerciseListItem from './ExerciseListItem';

function ExerciseList({
    items,
    hasMore,
    loading,
    sentinelRef,
    onToggleFavorite,
    onSelect,
    emptyIcon = 'fa-magnifying-glass',
    emptyText = 'Nessun esercizio trovato',
}) {
    return (
        <div className="exercise-list">
            {items.map((ex) => (
                <ExerciseListItem
                    key={ex.id}
                    ex={ex}
                    isFavorite={ex.is_favorite}
                    onToggleFavorite={onToggleFavorite}
                    onSelect={onSelect}
                />
            ))}
            {hasMore && <div ref={sentinelRef} style={{ height: 1 }} />}
            {loading && (
                <div className="text-center py-3 text-muted" style={{ fontSize: '0.8rem' }}>
                    <i className="fa-solid fa-spinner fa-spin me-1"></i>
                    Caricamento…
                </div>
            )}
            {!loading && !hasMore && items.length === 0 && (
                <div className="text-center py-5 text-muted">
                    <i className={`fa-solid ${emptyIcon} mb-2 d-block fs-4`}></i>
                    {emptyText}
                </div>
            )}
        </div>
    );
}

export default ExerciseList;
