import { useState, useEffect, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useInfiniteScroll } from './useInfiniteScroll';
import {
    fetchListPage, setActiveTab, setSearch,
    selectActiveTab, selectSearch, selectList,
    LIST_TIPES,
} from '../features/exercises/exercisesSlice';

// ─── Sub-hook interno ─────────────────────────────────────────────────────────
// Gestisce fetch di pagina 1 e pagine successive per una singola lista.
// Viene istanziato tre volte, una per tab ('all', 'favorites', 'custom').
// `enabled` è false quando la tab non è quella attiva, così nessun fetch
// viene avviato per le tab non visibili.
function useListControls(listKey, debouncedSearch, enabled) {
    const dispatch = useDispatch();
    // Snapshot Redux della lista corrispondente a questa tab
    const list = useSelector(selectList(listKey));

    // Effetto di sincronizzazione: se la tab diventa attiva oppure la query
    // debouncata cambia, verifica se i dati in cache sono già aggiornati.
    // Se no, carica pagina 1 (reset della lista).
    // `list.query` è escluso dalle dipendenze di proposito: vogliamo rieseguire
    // solo al cambio di `enabled` o `debouncedSearch`, non ad ogni risposta HTTP.
    useEffect(() => {
        if (!enabled) return;
        // query diversa da quella già caricata?
        if (list.query !== debouncedSearch) {
            dispatch(fetchListPage({ listKey, page: 1, query: debouncedSearch }));
        }

        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [enabled, debouncedSearch]);

    // Callback stabile per caricare la pagina successiva (richiamata dall'IntersectionObserver).
    // Non parte se c'è già un fetch in corso o se non ci sono altre pagine.
    const loadMore = useCallback(() => {
        if (list.loading || !list.hasMore) return;
        dispatch(fetchListPage({ listKey, page: list.page + 1, query: debouncedSearch }));
    }, [dispatch, listKey, list.loading, list.hasMore, list.page, debouncedSearch]);

    return { ...list, loadMore };
}

// ─── Hook principale ──────────────────────────────────────────────────────────
// Aggrega ricerca, cambio tab e infinite scroll per le tre liste della modale.
// Espone alla UI tutto ciò di cui ha bisogno: stato, handler e ref dei sentinel.
export function useExerciseSearch() {
    const dispatch = useDispatch();
    // Tab attiva condivisa globalmente via Redux ('all' | 'favorites' | 'custom')
    const activeTab = useSelector(selectActiveTab);
    // Stringa di ricerca grezza, aggiornata ad ogni keystroke
    const search = useSelector(selectSearch);

    // Il debounce è responsabilità puramente UI: aspetta 350 ms di silenzio
    // prima di propagare la query al layer di fetch, evitando una chiamata HTTP
    // per ogni singola lettera digitata.
    const [debouncedSearch, setDebouncedSearch] = useState(search);
    useEffect(() => {
        const t = setTimeout(() => setDebouncedSearch(search), 350);
        return () => clearTimeout(t); // cancella il timer se l'utente digita ancora
    }, [search]);

    // Un set di controlli (items, loading, hasMore, loadMore…) per ciascuna lista.
    // Solo la lista della tab attiva (enabled = true) eseguirà fetch reali.
    const allControls = useListControls('all', debouncedSearch, activeTab === 'all');
    const favoriteControls = useListControls('favorites', debouncedSearch, activeTab === 'favorites');
    const customControls = useListControls('custom', debouncedSearch, activeTab === 'custom');

    // Collega un ref DOM a un IntersectionObserver: quando il div sentinel in fondo
    // alla lista entra nel viewport, `loadMore` viene invocato automaticamente.
    // L'observer è attivo solo per la tab corrente e solo se ci sono altre pagine.
    const sentinelAll = useInfiniteScroll(allControls.loadMore, activeTab === 'all' && allControls.hasMore);
    const sentinelFavorite = useInfiniteScroll(favoriteControls.loadMore, activeTab === 'favorites' && favoriteControls.hasMore);
    const sentinelCustom = useInfiniteScroll(customControls.loadMore, activeTab === 'custom' && customControls.hasMore);

    // Cambiare tab azzera anche la search (lo fa lo slice internamente tramite setActiveTab)
    const handleTabChange = useCallback((key) => {
        dispatch(setActiveTab(key));
    }, [dispatch]);

    const handleSetSearch = useCallback((value) => {
        dispatch(setSearch(value));
    }, [dispatch]);

    return {
        search,
        setSearch: handleSetSearch,
        activeTab,
        handleTabChange,
        // Ogni lista porta con sé items, loading, hasMore e il ref del sentinel
        allList: { ...allControls, sentinelRef: sentinelAll },
        favoriteList: { ...favoriteControls, sentinelRef: sentinelFavorite },
        customList: { ...customControls, sentinelRef: sentinelCustom },
    };
}
