import { useState, useRef, useEffect } from 'react';
import ExerciseCard from './ExerciseCard';

function DayColumn({ day, index, days, onAddExercise, onEditExercise, onDeleteExercise, onDragStart, onDragEnd, onDragOver, onDrop, isDragOver, onCopyDay, onCopyExercise, dayErrors = {} }) {
    const [showCopyMenu, setShowCopyMenu] = useState(false);
    const menuRef = useRef(null);

    useEffect(() => {
        if (!showCopyMenu) return;
        const handleClick = (e) => {
            if (menuRef.current && !menuRef.current.contains(e.target)) {
                setShowCopyMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClick);
        return () => document.removeEventListener('mousedown', handleClick);
    }, [showCopyMenu]);

    const destinations = days.filter((d) => d.dayOfWeek !== day.dayOfWeek);

    return (
        <div
            className={`builder-day${isDragOver ? ' builder-day--drag-over' : ''}`}
            onDragOver={(e) => { e.preventDefault(); onDragOver(day.dayOfWeek); }}
            onDragLeave={() => onDragOver(null)}
            onDrop={() => onDrop(day.dayOfWeek)}
        >
            <div className="builder-day__header">
                <div className="d-flex align-items-center justify-content-between">
                    <div className="builder-day__label">Giorno {index + 1}</div>
                    {day.exercises.length > 0 && (
                        <div className="position-relative" ref={menuRef}>
                            <button
                                className="btn-icon"
                                title="Copia esercizi in un altro giorno"
                                onClick={() => setShowCopyMenu((v) => !v)}
                            >
                                <i className="fa-solid fa-copy"></i>
                            </button>
                            {showCopyMenu && (
                                <div className="context-menu">
                                    <div className="context-menu__header">
                                        <span>Copia in…</span>
                                        <button className="context-menu__close" onClick={() => setShowCopyMenu(false)}>
                                            <i className="fa-solid fa-xmark"></i>
                                        </button>
                                    </div>
                                    {destinations.map((dest) => (
                                        <button
                                            key={dest.dayOfWeek}
                                            className="context-menu__item"
                                            onClick={() => { onCopyDay(day.dayOfWeek, dest.dayOfWeek); setShowCopyMenu(false); }}
                                        >
                                            <span className="context-menu__num">G{days.indexOf(dest) + 1}</span>
                                            {dest.name}
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                </div>
                <div className="builder-day__name">{day.name}</div>
                {day.exercises.length > 0 && (
                    <div className="builder-day__count">{day.exercises.length} esercizi</div>
                )}
                <div className="builder-day__cta">
                    <button
                        className="btn-dashed"
                        onClick={() => onAddExercise(day.dayOfWeek)}
                    >
                        <i className="fa-solid fa-plus"></i>
                        Esercizio
                    </button>
                </div>
            </div>

            <div className="builder-day__body">
                {day.exercises.map((exercise, exerciseIndex) => (
                    <ExerciseCard
                        key={exercise.id}
                        exercise={exercise}
                        dayOfWeek={day.dayOfWeek}
                        onEdit={onEditExercise}
                        onDelete={(id) => onDeleteExercise(day.dayOfWeek, id)}
                        onCopyExercise={onCopyExercise}
                        days={days}
                        onDragStart={onDragStart}
                        onDragEnd={onDragEnd}
                        errors={dayErrors.exercises?.[exercise.id] || {}}
                    />
                ))}
                {day.exercises.length === 0 && (
                    <div className="builder-day__empty">
                        <i className="fa-solid fa-dumbbell"></i>
                        <span>Nessun esercizio</span>
                    </div>
                )}
            </div>
        </div>
    );
}

export default DayColumn;
