import { BaseService } from "./base.service";

export const WorkoutTemplatesService = {
    ...BaseService,

    basePath: '/workout-templates',

    getAll: function (params = {}) {
        return this.all({ url: '', params });
    },

    getById: function (id) {
        return this.read({ url: '', id });
    },

    createTemplate: function (data) {
        return this.create({ url: '', data });
    },
};
