import { useCallback } from 'react';
import { useDispatch } from 'react-redux';
import { Modal } from 'react-bootstrap';
import { useExerciseSearch } from '../../hooks/useExerciseSearch';
import ExerciseList from './ExerciseList';
import { LIST_TIPES, toggleFavoriteExercise } from '../../features/exercises/exercisesSlice';

function ExerciseSearchModal({ onClose, onSelect }) {
    const dispatch = useDispatch();
    const { search, setSearch, activeTab, handleTabChange, allList, favoriteList, customList } = useExerciseSearch();

    const toggleFavorite = useCallback((ex) => dispatch(toggleFavoriteExercise(ex.id)), [dispatch]);

    const handleSelectApi = (ex) => {
        onSelect({
            id: ex.id,
            name: ex.name,
            muscleGroup: ex.muscle_group_name ?? '',
            equipment: '',
            isFavorite: ex.is_favorite,
            isPersonal: false,
        });
    };

    return (
        <Modal show size="lg" onHide={onClose} centered dialogClassName="builder-modal">
            <Modal.Header closeButton>
                <Modal.Title>Aggiungi Esercizio</Modal.Title>
            </Modal.Header>
            <Modal.Body className="p-0">
                <div className="tab-bar border-bottom border-secondary">
                    {Object.keys(LIST_TIPES).map((t) => (
                        <button
                            key={t}
                            className={`tab-item${activeTab === t ? ' tab-item--active' : ''}`}
                            onClick={() => handleTabChange(t)}
                        >
                            {LIST_TIPES[t].label}
                        </button>
                    ))}
                </div>

                <div className="p-3">
                    <div className="input-group">
                        <span className="input-group-text">
                            <i className="fa-solid fa-magnifying-glass"></i>
                        </span>
                        <input
                            type="text"
                            className="form-control"
                            placeholder="Cerca esercizio o gruppo muscolare..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            autoFocus
                        />
                    </div>
                </div>

                {activeTab === 'all' && (
                    <ExerciseList
                        {...allList}
                        onToggleFavorite={toggleFavorite}
                        onSelect={handleSelectApi}
                    />
                )}
                {activeTab === 'favorites' && (
                    <ExerciseList
                        {...favoriteList}
                        onToggleFavorite={toggleFavorite}
                        onSelect={handleSelectApi}
                        emptyIcon="fa-star"
                        emptyText="Nessun esercizio preferito"
                    />
                )}
                {activeTab === 'custom' && (
                    <ExerciseList
                        {...customList}
                        onSelect={handleSelectApi}
                    />
                )}
            </Modal.Body>
        </Modal>
    );
}

export default ExerciseSearchModal;
