import { BaseService } from './base.service';

export const AthletesService = {
    ...BaseService,
    basePath: '/coach',

    getAthletes: function (params) {
        return this.all({ url: '/athletes', params });
    },

    getAthlete: function (userId) {
        return this.read({ url: '/athletes', id: userId });
    },

    searchUsers: function (q) {
        return this.all({ url: '/users/search', params: { q } });
    },

    addAthlete: function (data) {
        return this.create({ url: '/athletes/add', data });
    },

    removeAthlete: function (athleteId) {
        return this.request({ url: `/athletes/${athleteId}`, type: 'delete' });
    },

    getAthleteWorkouts: function (userId, params) {
        return this.all({ url: `/athletes/${userId}/workouts`, params });
    },

    getAthleteWorkout: function (athleteId, schedaId) {
        return this.read({ url: `/athletes/${athleteId}/workouts`, id: schedaId });
    },

    deleteAthleteWorkout: function (athleteId, schedaId) {
        return this.request({ url: `/athletes/${athleteId}/workouts/${schedaId}`, type: 'delete' });
    },
};
