function ExerciseListItem({ ex, isFavorite, onToggleFavorite, onSelect }) {
    return (
        <div className="list-item">
            <div className="list-item__icon">
                <i className="fa-regular fa-circle-play"></i>
            </div>
            <div className="list-item__info">
                <div className="list-item__name">{ex.name}</div>
                <div className="list-item__meta">
                    {ex.muscle_group_name && (
                        <span className="tag-pill">{ex.muscle_group_name}</span>
                    )}
                </div>
            </div>
            {onToggleFavorite && (
                <button
                    className={`btn-icon btn-favorite${isFavorite ? ' btn-favorite--active' : ''}`}
                    title={isFavorite ? 'Rimuovi dai preferiti' : 'Aggiungi ai preferiti'}
                    onClick={() => onToggleFavorite(ex)}
                >
                    <i className={`fa-star ${isFavorite ? 'fa-solid' : 'fa-regular'}`}></i>
                </button>
            )}
            <button className="btn-add-item" onClick={() => onSelect(ex)}>
                + Aggiungi
            </button>
        </div>
    );
}

export default ExerciseListItem;
