import React, { useEffect, useState } from 'react';
import { Badge, Button, Card, Modal } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import { ProfileService } from '../services/profile.service';
import { hideLoader, showLoader } from '../features/loader/loaderSlice';
import { fetchSessions, removeSession, removeAllOtherSessions } from '../features/user/userSlice';

// ── Micro-componenti locali ──────────────────────────────────────────────────

const DEVICE_ICONS = {
    Desktop: 'fa-desktop',
    Mobile: 'fa-mobile-alt',
    Tablet: 'fa-tablet-alt',
};

const DeviceIcon = ({ deviceType }) => (
    <i className={`fas ${DEVICE_ICONS[deviceType] || 'fa-laptop'}`} />
);

const SessionDetail = ({ icon, children }) => (
    <span className="profile-page__session-detail">
        <i className={`fas ${icon}`}></i>
        {children}
    </span>
);

const SessionItem = ({ session, formatDateTime, onDisconnect }) => (
    <div className={`profile-page__session-item${session.isCurrent ? ' profile-page__session-item--current' : ''}`}>
        <div className="profile-page__session-icon">
            <DeviceIcon deviceType={session.deviceType} />
        </div>
        <div className="profile-page__session-info">
            <div className="profile-page__session-header">
                <h5 className="profile-page__session-device">
                    {session.device}
                    {session.isCurrent && <Badge bg="success" className="ms-2">Attuale</Badge>}
                </h5>
            </div>
            <div className="profile-page__session-details">
                <SessionDetail icon="fa-network-wired">{session.ip}</SessionDetail>
                <SessionDetail icon="fa-clock">
                    {session.hasLastUsedAt
                        ? `Ultima attività: ${formatDateTime(session.lastActivity)}`
                        : `Creata il: ${formatDateTime(session.lastActivity)}`}
                </SessionDetail>
            </div>
        </div>
        {!session.isCurrent && (
            <div className="profile-page__session-actions">
                <Button variant="outline-danger" size="sm" onClick={() => onDisconnect(session)}>
                    <i className="fas fa-ban me-1"></i>
                    Disconnetti
                </Button>
            </div>
        )}
    </div>
);

// ── Componente principale ────────────────────────────────────────────────────

const SessionsCard = () => {
    const dispatch = useDispatch();
    const { sessions, sessionsLoading } = useSelector((state) => state.user);

    const [showModal, setShowModal] = useState(false);
    const [sessionToInvalidate, setSessionToInvalidate] = useState(null);

    useEffect(() => {
        if (sessions.length === 0) dispatch(fetchSessions());
    }, []);

    const formatDateTime = (dateString) =>
        new Date(dateString).toLocaleString('it-IT', {
            day: '2-digit', month: '2-digit', year: 'numeric',
            hour: '2-digit', minute: '2-digit',
        });

    const openModal = (session) => {
        setSessionToInvalidate(session);
        setShowModal(true);
    };

    const closeModal = () => {
        setShowModal(false);
        setSessionToInvalidate(null);
    };

    const handleInvalidate = async (sessionId) => {
        dispatch(showLoader());
        try {
            const { data } = await ProfileService.invalidateSession(sessionId);
            toast.success(data.message);
            dispatch(removeSession(sessionId));
            closeModal();
        } catch (error) {
            toast.error(error.response?.data?.message || 'Errore nell\'invalidazione della sessione');
        } finally {
            dispatch(hideLoader());
        }
    };

    const handleInvalidateAllOthers = async () => {
        dispatch(showLoader());
        try {
            const { data } = await ProfileService.invalidateAllOtherSessions();
            toast.success(data.message);
            dispatch(removeAllOtherSessions());
        } catch (error) {
            toast.error(error.response?.data?.message || 'Errore nell\'invalidazione delle sessioni');
        } finally {
            dispatch(hideLoader());
        }
    };

    const hasOtherSessions = sessions.some((s) => !s.isCurrent);

    return (
        <>
            <Card className="profile-page__card profile-page__card--sessions">
                <Card.Body>
                    <div className="profile-page__sessions-header">
                        <div>
                            <div className="d-flex align-items-center gap-2 mb-2">
                                <h2 className="profile-page__sessions-title mb-0">Sessioni attive</h2>
                                <Button
                                    variant="link"
                                    className="btn-reload"
                                    onClick={() => dispatch(fetchSessions())}
                                    disabled={sessionsLoading}
                                    size="sm"
                                    title="Ricarica sessioni"
                                >
                                    <i className={`fas fa-sync-alt${sessionsLoading ? ' fa-spin' : ''}`}></i>
                                </Button>
                            </div>
                            <p className="profile-page__sessions-subtitle">
                                Gestisci i dispositivi e le sessioni dove hai effettuato l'accesso
                            </p>
                        </div>
                        {hasOtherSessions && (
                            <Button variant="outline-danger" size="sm" onClick={handleInvalidateAllOthers}>
                                <i className="fas fa-sign-out-alt me-2"></i>
                                Disconnetti tutte le altre sessioni
                            </Button>
                        )}
                    </div>

                    <div className="profile-page__sessions-list">
                        {sessionsLoading ? (
                            <div className="profile-page__sessions-loading">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Caricamento...</span>
                                </div>
                                <p className="mt-3">Caricamento sessioni...</p>
                            </div>
                        ) : sessions.length === 0 ? (
                            <div className="profile-page__sessions-empty">
                                <i className="fas fa-info-circle"></i>
                                <p>Nessuna sessione trovata</p>
                            </div>
                        ) : (
                            sessions.map((session) => (
                                <SessionItem
                                    key={session.id}
                                    session={session}
                                    formatDateTime={formatDateTime}
                                    onDisconnect={openModal}
                                />
                            ))
                        )}
                    </div>
                </Card.Body>
            </Card>

            <Modal show={showModal} onHide={closeModal} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Conferma disconnessione</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <p>Sei sicuro di voler disconnettere questa sessione?</p>
                    {sessionToInvalidate && (
                        <div className="mt-3 p-3 bg-light rounded">
                            <strong>{sessionToInvalidate.device}</strong>
                            <br />
                            <small className="text-muted">{sessionToInvalidate.ip}</small>
                        </div>
                    )}
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="outline-secondary" onClick={closeModal}>Annulla</Button>
                    <Button variant="danger" onClick={() => handleInvalidate(sessionToInvalidate?.id)}>
                        Disconnetti
                    </Button>
                </Modal.Footer>
            </Modal>
        </>
    );
};

export default SessionsCard;
