const METADATA_MAP = {
    title: 'title',
    level: 'level',
    type: 'training_type',
    objective: 'objective',
    expiry: 'expiry',
    description: 'description',
    isTemplate: 'is_template',
    isGlobalTemplate: 'is_global_template',
    assignedUserId: 'assigned_user_id',
};

const TEMPLATE_MAP = {
    title: 'name',
    description: 'description',
    level: 'level',
    type: 'training_type',
    isGlobalTemplate: 'is_global',
};

const EXERCISE_MAP = {
    sets: 'sets',
    reps: 'reps',
    rest: 'rest',
};

function mapFields(source, fieldMap) {
    return Object.fromEntries(
        Object.entries(fieldMap).map(([from, to]) => [to, source[from]])
    );
}

function serializeDays(activeDays) {
    return activeDays.reduce((acc, d) => {
        acc[d.dayOfWeek] = {
            day_of_week: d.dayOfWeek,
            name: d.name,
            exercises: d.exercises.reduce((exAcc, ex) => {
                exAcc[ex.id] = {
                    exercise_id: ex.exercise?.id,
                    ...mapFields(ex, EXERCISE_MAP),
                };
                return exAcc;
            }, {}),
        };
        return acc;
    }, {});
}

export const serializeWorkoutPayload = (metadata, days) => {
    const activeDays = days.filter((d) => d.exercises.length > 0);
    const payload = mapFields(metadata, METADATA_MAP);
    payload.assigned_user_id ??= null;
    payload.days = serializeDays(activeDays);
    return payload;
};

export const serializeTemplatePayload = (metadata, days) => {
    const activeDays = days.filter((d) => d.exercises.length > 0);
    const payload = mapFields(metadata, TEMPLATE_MAP);
    payload.weekly_sessions = activeDays.length;
    payload.days = serializeDays(activeDays);
    return payload;
};

export const parseErrors = (errors) => {
    const general = {};
    const days = {};

    Object.keys(errors).forEach((key) => {
        if (key.startsWith('days.')) {
            const parts = key.split('.');
            const dayIdx = parts[1];
            const exIdx = parts[3];
            const property = parts[4];

            days[dayIdx] ??= { exercises: {} };
            days[dayIdx].exercises[exIdx] ??= {};
            days[dayIdx].exercises[exIdx][property] = errors[key][0];
        } else {
            general[key] = errors[key][0];
        }
    });

    return { general, days };
};
