import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import SchedaCreate from './pages/SchedaCreate';
import Scheda from './pages/Scheda';
import { Login } from './pages/auth/Login';
import ProtectedRoute from './components/ProtectedRoute';
import AdminRoute from './components/AdminRoute';
import CoachRoute from './components/CoachRoute';
import Allenamento from './pages/Allenamento';
import ErrorPage from './pages/ErrorPage';
import WorkoutList from './pages/WorkoutList';
import Register from './pages/auth/Register';
import DemoTimer from './pages/DemoTimer';
import Profilo from './pages/Profilo';
import Progress from './pages/Progress';
import ExercisesTable from './pages/ExercisesTable';
import CustomEserciziTable from './pages/CustomEserciziTable';
import WorkoutsBuiler from './pages/WorkoutsBuilder';
import AthletesList from './pages/coach/AthletesList';
import AthleteDetail from './pages/coach/AthleteDetail';
import AthleteWorkoutDetail from './pages/coach/AthleteWorkoutDetail';

const App = () => {
  return (
    <Router basename="/app">
      <Routes>
        {/* Redirect dalla root alla home desiderata */}
        <Route path="/" element={<Navigate to="/workouts/last" replace />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        {/* Rotta di test per lo sviluppo del timer */}
        <Route path="/demo/timer" element={<DemoTimer />} />

        {/* Rotte dove è richiesta l'autenticazione */}
        <Route element={<ProtectedRoute />}>
          <Route path="/workouts" element={<WorkoutList />} />
          <Route path="/workouts/:id" element={<Scheda />} />
          <Route path="/workouts/last" element={<Scheda />} />
          <Route path="workouts/:id/day/:day" element={<Allenamento />} />
          <Route path="workouts/last/day/:day" element={<Allenamento />} />
          <Route path="/scheda/create" element={<SchedaCreate />} />
          <Route path="/scheda/builder" element={<WorkoutsBuiler />} />
          <Route path="/profile" element={<Profilo />} />
          <Route path="/progress" element={<Progress />} />
          <Route path="/progress/:id" element={<Progress />} />
          <Route path="/custom-exercises" element={<CustomEserciziTable />} />
          {/* Rotte coach - protette da CoachRoute (tipoUtente 2 o 3) */}
          <Route element={<CoachRoute />}>
            <Route path="/coach/athletes" element={<AthletesList />} />
            <Route path="/coach/athletes/:userId" element={<AthleteDetail />} />
            <Route path="/coach/athletes/:userId/workouts/:schedaId" element={<AthleteWorkoutDetail />} />
          </Route>
          {/* Rotte admin - protette da middleware AdminRoute */}
          <Route element={<AdminRoute />}>
            <Route path="/exercises" element={<ExercisesTable />} />
          </Route>
        </Route>

        <Route path="/error" element={<ErrorPage />} />
        <Route path="*" element={<ErrorPage />} />
      </Routes>
    </Router>
  );
}

export default App;