import { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { formatDate } from '../../utils/date';
import {
    selectDays,
    selectTotalExercises,
    selectMetadata,
    addExercise,
    updateExercise,
    removeExercise,
    moveExercise,
    copyExercise,
    copyDay,
} from '../../features/workoutBuilder/workoutBuilderSlice';
import ExerciseSearchModal from '../ExerciseSearchModal';
import DayColumn from '../ProgramsBuilder/DayColumn';
import ExerciseConfigPanel from '../ProgramsBuilder/ExerciseConfigPanel';

function StepExercises({ daysErrors = {} }) {
    const dispatch = useDispatch();
    const days = useSelector(selectDays);
    const totalExercises = useSelector(selectTotalExercises);
    const { title, expiry } = useSelector(selectMetadata);

    // Stato locale per l'interazione UI: non finisce in Redux perché
    // è effimero (non serve essere persistito tra step o sessioni)
    const [targetDay, setTargetDay] = useState(null);
    const [editingExercise, setEditingExercise] = useState(null);
    const [showSearch, setShowSearch] = useState(false);
    const [showConfig, setShowConfig] = useState(false);
    const [drag, setDrag] = useState(null);
    const [dragOverDayId, setDragOverDayId] = useState(null);

    const openSearch = (dayOfWeek) => {
        setTargetDay(dayOfWeek);
        setShowSearch(true);
    };

    const handleExerciseSelected = (exercise) => {
        setShowSearch(false);
        // Prepopola il pannello di configurazione con valori di default ragionevoli
        // così l'utente parte già da una configurazione sensata (3×8-10, 90s)
        setEditingExercise({
            id: `we_${Date.now()}`,
            exerciseId: exercise.id,
            exercise,
            sets: 3,
            reps: '8-10',
            rest: 90,
        });
        setShowConfig(true);
    };

    const handleSaveConfig = (config) => {
        // Cerca se l'esercizio esiste già in uno dei giorni: se sì è una modifica,
        // altrimenti è un nuovo inserimento nel giorno target
        const ownerDay = days.find((d) => d.exercises.some((e) => e.id === config.id));
        if (ownerDay) {
            dispatch(updateExercise({ dayOfWeek: ownerDay.dayOfWeek, exercise: config }));
        } else {
            dispatch(addExercise({ dayOfWeek: targetDay, exercise: config }));
        }
        closeConfig();
    };

    const closeConfig = () => {
        setShowConfig(false);
        setEditingExercise(null);
        setTargetDay(null);
    };

    const handleEditExercise = (exercise) => {
        // Risale al giorno proprietario cercando per ID tra tutti i giorni
        const owner = days.find((d) => d.exercises.some((e) => e.id === exercise.id));
        setTargetDay(owner?.dayOfWeek ?? null);
        setEditingExercise(exercise);
        setShowConfig(true);
    };

    const handleDeleteExercise = (dayOfWeek, exerciseId) => {
        dispatch(removeExercise({ dayOfWeek, exerciseId }));
    };

    const handleDragStart = (exercise, sourceDayOfWeek) => {
        setDrag({ exercise, sourceDayOfWeek });
    };

    const handleDragEnd = () => {
        setDrag(null);
        setDragOverDayId(null);
    };

    const handleDrop = (tDayOfWeek) => {
        // Scarta il drop se non c'è nessun trascinamento attivo
        // o se sorgente e destinazione coincidono (no-op)
        if (!drag || drag.sourceDayOfWeek === tDayOfWeek) {
            handleDragEnd();
            return;
        }
        dispatch(moveExercise({
            sourceDayOfWeek: drag.sourceDayOfWeek,
            targetDayOfWeek: tDayOfWeek,
            exerciseId: drag.exercise.id,
        }));
        handleDragEnd();
    };

    const handleCopyExercise = (exercise, tDayOfWeek) => {
        dispatch(copyExercise({ targetDayOfWeek: tDayOfWeek, exercise }));
    };

    const handleCopyDay = (sourceDayOfWeek, tDayOfWeek) => {
        dispatch(copyDay({ sourceDay: sourceDayOfWeek, targetDay: tDayOfWeek }));
    };

    return (
        <div className="wizard-step-content wizard-step-content--exercises">
            <div className="d-flex justify-content-between align-items-center mb-3">
                <h5 className="wizard-step-title m-0">{title || 'Esercizi per giornata'}</h5>
                <div className="d-flex align-items-center gap-3">
                    {expiry && (
                        <span className="text-muted small">
                            <i className="far fa-clock me-1"></i>Scade il {formatDate(expiry, 'long')}
                        </span>
                    )}
                    {totalExercises > 0 && (
                        <span className="badge badge-level">{totalExercises} esercizi totali</span>
                    )}
                </div>
            </div>

            <div className="builder-columns-wrapper">
                <div className="builder-columns">
                    {days.map((day, index) => (
                        <DayColumn
                            key={day.dayOfWeek}
                            day={day}
                            index={index}
                            onAddExercise={openSearch}
                            onEditExercise={handleEditExercise}
                            onDeleteExercise={handleDeleteExercise}
                            onDragStart={handleDragStart}
                            onDragEnd={handleDragEnd}
                            onDragOver={setDragOverDayId}
                            onDrop={handleDrop}
                            isDragOver={dragOverDayId === day.dayOfWeek}
                            days={days}
                            onCopyDay={handleCopyDay}
                            onCopyExercise={handleCopyExercise}
                            dayErrors={daysErrors[day.dayOfWeek] || {}}
                        />
                    ))}
                </div>
            </div>

            {showSearch && (
                <ExerciseSearchModal
                    onClose={() => setShowSearch(false)}
                    onSelect={handleExerciseSelected}
                />
            )}

            {showConfig && editingExercise && (
                <ExerciseConfigPanel
                    exercise={editingExercise}
                    onClose={closeConfig}
                    onSave={handleSaveConfig}
                    errors={daysErrors[targetDay]?.exercises?.[editingExercise.id] || {}}
                />
            )}
        </div>
    );
}

export default StepExercises;
