import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { DAYS_OF_WEEK } from '../../pages/WorkoutsBuilder/data';
import { showLoader, hideLoader } from '../loader/loaderSlice';
import { WorkoutOptionsService } from '../../services/workoutOptions.service';

export const fetchWorkoutOptions = createAsyncThunk(
    'workoutBuilder/fetchWorkoutOptions',
    async (_, { dispatch, rejectWithValue }) => {
        try {
            dispatch(showLoader());
            const { data } = await WorkoutOptionsService.getOptions();
            return data.data;
        } catch (err) {
            return rejectWithValue(err.response?.data);
        } finally {
            dispatch(hideLoader());
        }
    }
);

// Factory function invece di un valore costante: ogni chiamata produce
// un array fresco con esercizi vuoti, evitando mutazioni accidentali
// dello stato iniziale tra un reset e l'altro.
const makeInitialDays = () => DAYS_OF_WEEK.map((d) => ({ ...d, exercises: [] }));

const initialMetadata = {
    title: '',
    level: '',
    type: '',
    objective: '',
    expiry: '',
    description: '',
    isTemplate: false,
    isGlobalTemplate: false,
    assignedUserId: null,
};

const initialState = {
    currentStep: 0,
    metadata: initialMetadata,
    days: makeInitialDays(),
    options: {
        loaded: false,
        levels: [],
        training_types: [],
        objectives: [],
    },
};

const workoutBuilderSlice = createSlice({
    name: 'workoutBuilder',
    initialState,
    reducers: {
        setStep: (state, { payload }) => {
            state.currentStep = payload;
        },
        // Merge parziale: aggiorna solo i campi passati, preserva gli altri
        updateMetadata: (state, { payload }) => {
            state.metadata = { ...state.metadata, ...payload };
        },
        addExercise: (state, { payload: { dayOfWeek, exercise } }) => {
            const day = state.days.find((d) => d.dayOfWeek === dayOfWeek);
            if (day) day.exercises.push(exercise);
        },
        removeExercise: (state, { payload: { dayOfWeek, exerciseId } }) => {
            const day = state.days.find((d) => d.dayOfWeek === dayOfWeek);
            if (day) day.exercises = day.exercises.filter((e) => e.id !== exerciseId);
        },
        updateExercise: (state, { payload: { dayOfWeek, exercise } }) => {
            const day = state.days.find((d) => d.dayOfWeek === dayOfWeek);
            if (!day) return;
            const idx = day.exercises.findIndex((e) => e.id === exercise.id);
            if (idx !== -1) day.exercises[idx] = exercise;
        },
        moveExercise: (state, { payload: { sourceDayOfWeek, targetDayOfWeek, exerciseId } }) => {
            // Stesso giorno sorgente e destinazione: nessuna operazione necessaria
            if (sourceDayOfWeek === targetDayOfWeek) return;
            const source = state.days.find((d) => d.dayOfWeek === sourceDayOfWeek);
            const target = state.days.find((d) => d.dayOfWeek === targetDayOfWeek);
            if (!source || !target) return;
            const exercise = source.exercises.find((e) => e.id === exerciseId);
            if (!exercise) return;
            source.exercises = source.exercises.filter((e) => e.id !== exerciseId);
            target.exercises.push(exercise);
        },
        copyExercise: (state, { payload: { targetDayOfWeek, exercise } }) => {
            const target = state.days.find((d) => d.dayOfWeek === targetDayOfWeek);
            if (target) {
                // Nuovo ID per la copia: evita collisioni con l'originale
                target.exercises.push({ ...exercise, id: `we_${Date.now()}_copy` });
            }
        },
        copyDay: (state, { payload: { sourceDay, targetDay } }) => {
            const source = state.days.find((d) => d.dayOfWeek === sourceDay);
            const target = state.days.find((d) => d.dayOfWeek === targetDay);
            if (!source || !target) return;
            // Indice i nell'ID garantisce unicità anche se più copie avvengono
            // nello stesso millisecondo (Date.now() potrebbe non cambiare)
            const copies = source.exercises.map((e, i) => ({ ...e, id: `we_${Date.now()}_${i}` }));
            // Aggiunge in coda senza sovrascrivere gli esercizi già presenti nel giorno target
            target.exercises = [...target.exercises, ...copies];
        },
        initFromTemplate: (state, { payload }) => {
            state.metadata = {
                title: payload.name ?? '',
                level: payload.level ?? '',
                type: payload.training_type ?? '',
                objective: '',
                expiry: '',
                description: payload.description ?? '',
                isTemplate: false,
                isGlobalTemplate: false,
                assignedUserId: null,
            };
            state.days = makeInitialDays();
            if (Array.isArray(payload.exercises)) {
                payload.exercises.forEach((ex, index) => {
                    const day = state.days.find((d) => d.dayOfWeek === ex.day);
                    if (!day) return;
                    day.exercises.push({
                        id: `we_${Date.now()}_${index}`,
                        exerciseId: ex.exercise?.id,
                        exercise: ex.exercise,
                        sets: ex.total_sets,
                        reps: String(ex.reps),
                        rest: ex.rest_per_set,
                        notes: ex.notes ?? '',
                    });
                });
            }
            state.currentStep = 0;
        },
        // RTK pattern: restituire un nuovo oggetto dal reducer equivale a
        // sostituire interamente lo stato (immer lo gestisce correttamente)
        resetBuilder: (state) => ({
            currentStep: 0,
            metadata: { ...initialMetadata },
            days: makeInitialDays(),
            options: state.options, // le options restano: non serve ricaricarle al prossimo wizard
        }),
    },
    extraReducers: (builder) => {
        builder.addCase(fetchWorkoutOptions.fulfilled, (state, { payload }) => {
            const toOptions = (obj) => Object.entries(obj).map(([value, name]) => ({ value, name }));
            state.options.levels = toOptions(payload.levels);
            state.options.training_types = toOptions(payload.training_types);
            state.options.objectives = toOptions(payload.objectives);
            state.options.loaded = true;
        });
    },
});

export const {
    setStep,
    updateMetadata,
    addExercise,
    removeExercise,
    updateExercise,
    moveExercise,
    copyExercise,
    copyDay,
    initFromTemplate,
    resetBuilder,
} = workoutBuilderSlice.actions;

export const selectCurrentStep = (state) => state.workoutBuilder.currentStep;
export const selectMetadata = (state) => state.workoutBuilder.metadata;
export const selectDays = (state) => state.workoutBuilder.days;
export const selectWorkoutOptions = (state) => state.workoutBuilder.options;
export const selectTotalExercises = (state) =>
    state.workoutBuilder.days.reduce((sum, d) => sum + d.exercises.length, 0);

export default workoutBuilderSlice.reducer;
