import React from 'react';

const formatDate = (dateString) => {
    if (!dateString) return null;
    return new Date(dateString).toLocaleDateString('it-IT', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
    });
};

const CoachSchedaHeader = ({ workout, onBack, onDelete }) => {
    const totalExercises = Object.values(workout.esercizi_x_day || {}).flat().length;
    const totalDays = workout.numeroAllSettimanali;

    return (
        <div className="scheda-header mb-4">
            <div className="scheda-header__content">
                <div className="scheda-header__main">
                    <div className="scheda-header__title-section">
                        <div className="scheda-header__title-row">
                            {onBack && (
                                <button className="scheda-header__back" onClick={onBack} title="Torna indietro">
                                    <i className="fas fa-chevron-left" />
                                </button>
                            )}
                            <h1 className="scheda-header__title">{workout.nomeScheda}</h1>
                        </div>
                        <div className="scheda-header__meta">
                            <span className="meta-item">
                                <i className="fas fa-calendar-days" />
                                {totalDays} {totalDays === 1 ? 'giorno' : 'giorni'}
                            </span>
                            <span className="meta-item">
                                <i className="fas fa-dumbbell" />
                                {totalExercises} {totalExercises === 1 ? 'esercizio' : 'esercizi'}
                            </span>
                            {workout.dataDiScadenza && (
                                <span className="meta-item">
                                    <i className="fas fa-clock" />
                                    Scade il {formatDate(workout.dataDiScadenza)}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                {onDelete && (
                    <div className="scheda-header__actions">
                        <button
                            className="scheda-header__btn scheda-header__btn--danger"
                            onClick={onDelete}
                        >
                            <i className="fas fa-trash" />
                            <span>Elimina</span>
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default CoachSchedaHeader;
