import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Alert } from 'react-bootstrap';
import { useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import BaseLayout from '../../components/BaseLayout';
import PageHeader from '../../components/PageHeader';
import UserProfileCard from '../../components/UserProfileCard';
import WorkoutCardGrid from '../../components/WorkoutCardGrid';
import { AthletesService } from '../../services/athletes.service';
import { hideLoader, showLoader } from '../../features/loader/loaderSlice';

const AthleteDetail = () => {
    const { userId } = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();

    const [athlete, setAthlete] = useState(null);
    const [workouts, setWorkouts] = useState([]);
    const [error, setError] = useState(null);

    useEffect(() => {
        const load = async () => {
            dispatch(showLoader());
            setError(null);
            try {
                const [athleteRes, workoutsRes] = await Promise.all([
                    AthletesService.getAthlete(userId),
                    AthletesService.getAthleteWorkouts(userId),
                ]);
                setAthlete(athleteRes.data?.data ?? athleteRes.data ?? null);
                const wData = workoutsRes.data?.data ?? workoutsRes.data ?? [];
                setWorkouts(Array.isArray(wData) ? wData : []);
            } catch (err) {
                setError(err.response?.data?.message || 'Errore nel caricamento dei dati');
            } finally {
                dispatch(hideLoader());
            }
        };
        load();
    }, [userId]);

    const handleDeleteWorkout = async (schedaId) => {
        dispatch(showLoader());
        try {
            const { data } = await AthletesService.deleteAthleteWorkout(userId, schedaId);
            toast.success(data?.message || 'Scheda eliminata con successo');
            setWorkouts((prev) => prev.filter((w) => w.idScheda !== schedaId));
        } catch (err) {
            toast.error(err.response?.data?.message || "Errore durante l'eliminazione della scheda");
        } finally {
            dispatch(hideLoader());
        }
    };

    const athleteName = athlete
        ? [athlete.nome, athlete.cognome].filter(Boolean).join(' ') || athlete.username
        : '';

    return (
        <BaseLayout>
            <div className="page-content athlete-detail">
                {athlete && (
                    <nav className="breadcrumb-nav">
                        <button
                            className="breadcrumb-nav__back"
                            onClick={() => navigate('/coach/athletes')}
                        >
                            Atleti
                        </button>
                        <span className="breadcrumb-nav__separator">/</span>
                        <span className="breadcrumb-nav__current">{athleteName}</span>
                    </nav>
                )}
                <PageHeader
                    title={athleteName || 'Dettaglio Atleta'}
                    subtitle="Profilo e schede workout dell'atleta"
                    onBack={athlete ? () => navigate('/coach/athletes') : undefined}
                />

                {error && (
                    <Alert variant="danger" dismissible>
                        {error}
                    </Alert>
                )}

                {athlete && (
                    <>
                        {/* Profilo atleta */}
                        <UserProfileCard user={athlete} />

                        {/* Lista schede workout */}
                        <h5 className="athlete-detail__section-heading mb-3">
                            <i className="fas fa-dumbbell me-2"></i>
                            Schede Workout ({workouts.length})
                        </h5>

                        <WorkoutCardGrid
                            workouts={workouts}
                            getLinkTo={(w) => `/coach/athletes/${userId}/workouts/${w.idScheda}`}
                            onDelete={handleDeleteWorkout}
                            emptyMessage="Nessuna scheda workout assegnata a questo atleta."
                        />
                    </>
                )}
            </div>
        </BaseLayout>
    );
};

export default AthleteDetail;
