import { useState } from 'react';
import { useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import BaseLayout from '../../components/BaseLayout';
import WizardContainer from '../../components/WorkoutBuilder/WizardContainer';
import WorkoutTemplateList from './WorkoutTemplateList';
import { initFromTemplate, resetBuilder } from '../../features/workoutBuilder/workoutBuilderSlice';
import { showLoader, hideLoader } from '../../features/loader/loaderSlice';
import { WorkoutTemplatesService } from '../../services/workoutTemplates.service';

function WorkoutsBuilder() {
    const dispatch = useDispatch();
    const [showWizard, setShowWizard] = useState(false);

    const handleNewProgram = () => {
        dispatch(resetBuilder());
        setShowWizard(true);
    };

    const handleSelectTemplate = async (template) => {
        dispatch(showLoader());
        try {
            const { data } = await WorkoutTemplatesService.getById(template.id);
            dispatch(initFromTemplate(data.data));
            setShowWizard(true);
        } catch {
            toast.error('Errore nel caricamento del template. Riprova.');
        } finally {
            dispatch(hideLoader());
        }
    };

    const handleWizardClose = () => {
        setShowWizard(false);
    };

    return (
        <BaseLayout>
            {showWizard ? (
                <WizardContainer
                    onComplete={handleWizardClose}
                    onCancel={handleWizardClose}
                />
            ) : (
                <WorkoutTemplateList
                    onNewProgram={handleNewProgram}
                    onSelectTemplate={handleSelectTemplate}
                />
            )}
        </BaseLayout>
    );
}

export default WorkoutsBuilder;
