import React from 'react';
import { Col, Row } from 'react-bootstrap';
import WorkoutCard from './WorkoutCard';

const WorkoutCardGrid = ({
    workouts,
    getLinkTo,
    onDelete,
    emptyMessage = 'Nessuna scheda workout trovata.',
}) => {
    if (workouts.length === 0) {
        return (
            <div className="workout-card__empty">
                <i className="fas fa-dumbbell fa-2x mb-3 d-block"></i>
                <p className="mb-0">{emptyMessage}</p>
            </div>
        );
    }

    return (
        <Row className="g-4">
            {workouts.map((workout) => (
                <Col key={workout.idScheda} md={4}>
                    <WorkoutCard
                        workout={workout}
                        linkTo={getLinkTo(workout)}
                        onDelete={onDelete}
                    />
                </Col>
            ))}
        </Row>
    );
};

export default WorkoutCardGrid;
