import React from 'react';
import { Link } from 'react-router-dom';
import { formatDate } from '../utils/date';

const InfoItem = ({ icon, label, value }) => (
    <div className="workout-card__info-item">
        <i className={icon}></i>
        <div>
            <span className="workout-card__info-label">{label}</span>
            <span className="workout-card__info-value">{value}</span>
        </div>
    </div>
);

const WorkoutCard = ({ workout, linkTo, onDelete }) => {
    const handleDelete = () => {
        if (window.confirm('Sei sicuro di voler eliminare questa scheda?')) {
            onDelete(workout.idScheda);
        }
    };

    return (
        <div className="workout-card">
            <div className="workout-card__header">
                <div className="workout-card__icon">
                    <i className="fa-solid fa-dumbbell"></i>
                </div>
                <h3 className="workout-card__title">{workout.nomeScheda}</h3>
            </div>
            <div className="workout-card__body">
                <div className="workout-card__info">
                    <InfoItem
                        icon="fa-solid fa-bullseye"
                        label="Allenamenti"
                        value={`${workout.numeroAllSettimanali || 'ND'}/settimana`}
                    />
                    {workout.dataDiScadenza && (
                        <InfoItem
                            icon="fa-solid fa-calendar-days"
                            label="Scadenza"
                            value={formatDate(workout.dataDiScadenza)}
                        />
                    )}
                </div>
            </div>
            <div className="workout-card__footer d-flex justify-content-between align-items-center">
                <Link to={linkTo} className="workout-card__link">
                    Apri scheda <i className="fa-solid fa-arrow-right"></i>
                </Link>
                {onDelete && (
                    <button
                        className="btn btn-sm btn-outline-danger"
                        onClick={handleDelete}
                        title="Elimina scheda"
                    >
                        <i className="fas fa-trash"></i>
                    </button>
                )}
            </div>
        </div>
    );
};

export default WorkoutCard;
