import { BaseService } from "./base.service";

export const FavoriteExercisesService = {
    ...BaseService,

    basePath: '/favorites/exercises',

    getAll: function (params = {}) {
        return this.all({ url: '', params });
    },

    add: function (exerciseId) {
        return this.create({ url: `/${exerciseId}` });
    },

    toggle: function (exerciseId) {
        return this.create({ url: `/${exerciseId}/toggle` });
    },
};
