import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Alert, Button, Card, Form, Modal } from 'react-bootstrap';
import Select from 'react-select';
import { useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import BaseLayout from '../../components/BaseLayout';
import PageHeader from '../../components/PageHeader';
import DataTable from '../../components/Datatable/DataTable';
import ActionsDropdown from '../../components/ActionsDropdown';
import useDataTable from '../../hooks/useDataTable';
import { AthletesService } from '../../services/athletes.service';
import { hideLoader, showLoader } from '../../features/loader/loaderSlice';

const AthletesList = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();

    const {
        data: athletes,
        loading,
        error,
        totalItems,
        page,
        pageSize,
        totalPages,
        startItem,
        endItem,
        pageSizeOptions,
        setPage,
        setPageSize,
        goToNextPage,
        goToPrevPage,
        sortField,
        sortOrder,
        toggleSort,
        setData: setAthletes,
    } = useDataTable({
        fetchFn: (params) => AthletesService.getAthletes(params),
        defaultPageSize: 15,
        defaultSortField: 'cognome',
        defaultSortOrder: 'asc',
        pageSizeOptions: [15, 25, 50],
    });

    const [showModal, setShowModal] = useState(false);
    const [options, setOptions] = useState([]);
    const [searchLoading, setSearchLoading] = useState(false);
    const [selectedUser, setSelectedUser] = useState(null);
    const [addLoading, setAddLoading] = useState(false);
    const [addError, setAddError] = useState('');
    let debounceTimeout;

    const loadOptions = async (query) => {
        setSearchLoading(true);
        try {
            const { data } = await AthletesService.searchUsers(query);
            setOptions(data?.data || []);
        } catch {
            setOptions([]);
        } finally {
            setSearchLoading(false);
        }
    };

    const handleInputChange = (inputValue) => {
        clearTimeout(debounceTimeout);
        if (!inputValue || inputValue.trim().length < 2) {
            setOptions([]);
            return;
        }
        debounceTimeout = setTimeout(() => {
            loadOptions(inputValue.trim());
        }, 400);
    };

    const resetModalState = () => {
        setOptions([]);
        setSearchLoading(false);
        setSelectedUser(null);
        setAddError('');
    };

    const handleOpenModal = () => {
        resetModalState();
        setShowModal(true);
    };

    const handleCloseModal = () => {
        resetModalState();
        setShowModal(false);
    };

    const handleAddAthlete = async (e) => {
        e.preventDefault();
        if (!selectedUser) {
            setAddError("Seleziona un atleta dalla lista.");
            return;
        }
        setAddLoading(true);
        setAddError('');
        try {
            const { data } = await AthletesService.addAthlete({ athlete_id: selectedUser.value });
            toast.success(data?.message || 'Atleta aggiunto con successo');
            handleCloseModal();
            const { data: refreshed } = await AthletesService.getAthletes();
            setAthletes(refreshed?.data || []);
        } catch (err) {
            setAddError(err.response?.data?.message || "Errore durante l'aggiunta dell'atleta");
        } finally {
            setAddLoading(false);
        }
    };

    const handleRemove = async (athleteId) => {
        if (!window.confirm('Sei sicuro di voler rimuovere questo atleta?')) return;
        dispatch(showLoader());
        try {
            const { data } = await AthletesService.removeAthlete(athleteId);
            toast.success(data?.message || 'Atleta rimosso con successo');
            setAthletes((prev) => prev.filter((a) => a.idUtente !== athleteId));
        } catch (err) {
            toast.error(err.response?.data?.message || "Errore durante la rimozione dell'atleta");
        } finally {
            dispatch(hideLoader());
        }
    };

    const renderName = (athlete) => {
        const name = [athlete.nome, athlete.cognome].filter(Boolean).join(' ');
        return name || <span className="text-muted">-</span>;
    };

    const columns = [
        { key: 'nome', label: 'Nome', sortable: true, render: renderName },
        { key: 'username', label: 'Username', sortable: true },
        { key: 'email', label: 'Email', sortable: true },
    ];

    return (
        <BaseLayout>
            <div className="page-content">
                <PageHeader
                    title="I miei Atleti"
                    subtitle="Visualizza e gestisci gli atleti associati al tuo profilo"
                    actions={[
                        <Button key="add" variant="primary" onClick={handleOpenModal}>
                            <i className="fas fa-plus me-2"></i>
                            Aggiungi Atleta
                        </Button>,
                    ]}
                />

                {error && (
                    <Alert variant="danger" dismissible>
                        Errore nel caricamento degli atleti: {error}
                    </Alert>
                )}

                <Card className="datatable-card">
                    <Card.Body>
                        <DataTable
                            columns={columns}
                            data={athletes}
                            loading={loading}
                            emptyMessage="Nessun atleta associato"
                            tableClassName="athletes-table"
                            showActions={true}
                            rowKey="idUtente"
                            renderActions={(athlete) => (
                                <ActionsDropdown
                                    items={[
                                        {
                                            label: 'Dettaglio',
                                            icon: 'fas fa-eye',
                                            onClick: () => navigate(`/coach/athletes/${athlete.idUtente}`),
                                        },
                                        {
                                            label: 'Rimuovi',
                                            icon: 'fas fa-user-minus',
                                            variant: 'danger',
                                            onClick: () => handleRemove(athlete.idUtente),
                                        },
                                    ]}
                                />
                            )}
                            sortField={sortField}
                            sortOrder={sortOrder}
                            toggleSort={toggleSort}
                            startItem={startItem}
                            endItem={endItem}
                            totalItems={totalItems}
                            pageSize={pageSize}
                            setPageSize={setPageSize}
                            pageSizeOptions={pageSizeOptions}
                            page={page}
                            totalPages={totalPages}
                            setPage={setPage}
                            goToPrevPage={goToPrevPage}
                            goToNextPage={goToNextPage}
                        />
                    </Card.Body>
                </Card>
            </div>

            <Modal show={showModal} onHide={handleCloseModal} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Aggiungi Atleta</Modal.Title>
                </Modal.Header>
                <Form onSubmit={handleAddAthlete}>
                    <Modal.Body>
                        <Form.Group>
                            <Form.Label>Cerca atleta</Form.Label>
                            <Select
                                options={options}
                                value={selectedUser}
                                onChange={(option) => { setSelectedUser(option); setAddError(''); }}
                                onInputChange={handleInputChange}
                                placeholder="Cerca per email o nome…"
                                isClearable
                                isLoading={searchLoading}
                                isDisabled={addLoading}
                                noOptionsMessage={({ inputValue }) =>
                                    !inputValue || inputValue.trim().length < 2
                                        ? 'Digita almeno 2 caratteri per cercare'
                                        : 'Nessun risultato'
                                }
                                classNamePrefix="wp_select"
                            />
                            {addError && <div className="text-danger mt-1 small">{addError}</div>}
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button variant="outline-secondary" onClick={handleCloseModal} disabled={addLoading}>
                            Annulla
                        </Button>
                        <Button variant="primary" type="submit" disabled={addLoading || !selectedUser}>
                            {addLoading ? (
                                <>
                                    <i className="fas fa-spinner fa-spin me-2"></i>
                                    Aggiunta in corso…
                                </>
                            ) : (
                                <>
                                    <i className="fas fa-plus me-2"></i>
                                    Aggiungi
                                </>
                            )}
                        </Button>
                    </Modal.Footer>
                </Form>
            </Modal>
        </BaseLayout>
    );
};

export default AthletesList;
