import { useEffect, useRef } from 'react';

/**
 * Collega un elemento sentinel all'IntersectionObserver.
 * Quando il sentinel entra nel viewport, chiama `onEndReached`.
 *
 * @param {Function} onEndReached - Callback invocata al raggiungimento del fondo.
 * @param {boolean}  enabled      - Se false, l'observer non viene attivato (es. quando non c'è più nulla da caricare).
 *
 * @returns {React.RefObject} sentinelRef — da assegnare all'elemento sentinel nel JSX.
 *
 * @example
 * const sentinelRef = useInfiniteScroll(loadMore, hasMore);
 * <div ref={sentinelRef} />
 */
export function useInfiniteScroll(onEndReached, enabled = true) {
    const sentinelRef = useRef(null);

    useEffect(() => {
        if (!enabled) return;
        const el = sentinelRef.current;
        if (!el) return;

        const observer = new IntersectionObserver(
            ([entry]) => { if (entry.isIntersecting) onEndReached(); },
            { threshold: 0.1 }
        );
        observer.observe(el);
        return () => observer.disconnect();
    }, [onEndReached, enabled]);

    return sentinelRef;
}
