import { useDispatch, useSelector } from 'react-redux';
import {
	selectMetadata,
	selectDays,
	selectWorkoutOptions,
	updateMetadata,
} from '../../features/workoutBuilder/workoutBuilderSlice';
import { useAuth } from '../../hooks/useAuth';
import { InputError } from '../FormComponents';
import ToggleRow from '../ToggleRow';
import { formatDate } from '../../utils/date';

function StepSummary({ fieldErrors = {}, athletes = [] }) {
	const dispatch = useDispatch();
	const { isAdmin, isCoach } = useAuth();
	const metadata = useSelector(selectMetadata);
	const options = useSelector(selectWorkoutOptions);
	const days = useSelector(selectDays);

	const label = (list, value) => list.find((o) => o.value === value)?.name ?? value;
	const activeDays = days.filter((d) => d.exercises.length > 0);

	const set = (field, value) => dispatch(updateMetadata({ [field]: value }));
	const showUserSelect = (isAdmin || isCoach) && !metadata.isTemplate;

	return (
		<>
			<div className="summary-meta-card">
				<h4 className="summary-program-name">{metadata.title}</h4>

				{(metadata.level || metadata.type || metadata.objective) && (
					<div className="summary-meta-badges">
						{metadata.level && <span className="tag-pill">{label(options.levels, metadata.level)}</span>}
						{metadata.type && <span className="tag-pill">{label(options.training_types, metadata.type)}</span>}
						{metadata.objective && <span className="tag-pill">{label(options.objectives, metadata.objective)}</span>}
					</div>
				)}

				{metadata.expiry && (
					<p className="summary-meta-line">
						<i className="far fa-clock me-1"></i>
						Scade il {formatDate(metadata.expiry, 'long')}
					</p>
				)}

				{metadata.description && (
					<div
						className="summary-description"
						dangerouslySetInnerHTML={{ __html: metadata.description }}
					/>
				)}

				<div className="mt-3">
					<ToggleRow
						id="summary-template-switch"
						label="Crea come modello"
						tooltip="Torna al passo 1 per modificarla."
						checked={metadata.isTemplate}
						disabled
						className="summary-toggle"
					/>

					{metadata.isTemplate && (
						<ToggleRow
							id="summary-global-template-switch"
							label="Modello globale"
							tooltip="Torna al passo 1 per modificarla."
							checked={metadata.isGlobalTemplate}
							disabled
							className="summary-toggle mt-2"
						/>
					)}
				</div>

				{showUserSelect && (
					<div className="mt-3">
						<label className="form-group-label mb-1" htmlFor="summary-user-select">
							Assegna a un atleta
						</label>
						<select
							id="summary-user-select"
							className={`form-select${fieldErrors.assigned_user_id ? ' is-invalid' : ''}`}
							value={metadata.assignedUserId ?? ''}
							onChange={(e) => set('assignedUserId', e.target.value || null)}
						>
							<option value="">Nessun atleta assegnato</option>
							{athletes.map((u) => (
								<option key={u.idUtente} value={u.idUtente}>
									{(u.nome || u.cognome)
										? `${u.nome ?? ''} ${u.cognome ?? ''}`.trim()
										: u.username}
								</option>
							))}
						</select>
						<InputError error={fieldErrors.assigned_user_id} />
						<small className="text-muted mt-1 d-block">
							<i className="fa-solid fa-circle-info me-1"></i>
							Senza selezione, la scheda sarà assegnata a te.
						</small>
					</div>
				)}
			</div>

			{activeDays.length === 0 ? (
				<div className="text-muted text-center py-5">
					<i className="fa-solid fa-dumbbell fa-2x mb-3 d-block opacity-25"></i>
					<p className="mb-0">Nessun esercizio nel programma.</p>
					<small>Aggiungi esercizi nella schermata precedente.</small>
				</div>
			) : (
				<div className="summary-days">
					{activeDays.map((day) => (
						<div key={day.dayOfWeek} className="summary-day">
							<div className="summary-day__header">
								<div className="summary-day__info">
									<span className="summary-day__name">{day.name}</span>
									<span className="summary-day__num">Giorno {day.dayOfWeek}</span>
								</div>
								<div className="summary-day__count">
									<span className="summary-day__count-num">{day.exercises.length}</span>
									<span className="summary-day__count-label">esercizi</span>
								</div>
							</div>
							<ul className="summary-exercises">
								{day.exercises.map((ex) => (
									<li key={ex.id} className="summary-exercise">
										<span className="summary-exercise__name">
											{ex.exercise?.name ?? 'Esercizio'}
										</span>
										<span className="summary-exercise__params">
											{ex.sets}×{ex.reps}
											<span className="summary-exercise__sep">·</span>
											{ex.rest}s
										</span>
									</li>
								))}
							</ul>
						</div>
					))}
				</div>
			)}
		</>
	);
}

export default StepSummary;
