import React, { useState } from 'react';
import { Input, Textarea } from '../FormComponents';

function ExerciseConfigPanel({ exercise, onClose, onSave, errors = {} }) {
    const [config, setConfig] = useState(exercise);

    const set = (field, value) => setConfig((c) => ({ ...c, [field]: value }));

    const handleSubmit = (e) => {
        e.preventDefault();
        onSave(config);
    };

    return (
        <div className="config-panel">
            <div className="config-panel__overlay" onClick={onClose} />
            <div className="config-panel__content">
                <div className="config-panel__header">
                    <h5 className="m-0 text-truncate flex-shrink-1 min-w-0">{config.exercise.name}</h5>
                    <button className="btn-icon flex-shrink-0" onClick={onClose}>
                        <i className="fa-solid fa-xmark"></i>
                    </button>
                </div>

                <form
                    id="exercise-config-form"
                    className="config-panel__body"
                    onSubmit={handleSubmit}
                >
                    <div className="section-label">Parametri principali</div>
                    <div className="row g-3 mb-3">
                        <div className="col-4">
                            <Input
                                name="sets"
                                title="Serie"
                                type="number"
                                required
                                min="1"
                                placeholder="3"
                                value={config.sets}
                                onInput={(e) => set('sets', parseInt(e.target.value) || 1)}
                                error={errors.sets}
                            />
                        </div>
                        <div className="col-4">
                            <Input
                                name="reps"
                                title="Rip."
                                type="text"
                                required
                                placeholder="8-10"
                                value={config.reps}
                                onInput={(e) => set('reps', e.target.value)}
                                error={errors.reps}
                            />
                        </div>
                        <div className="col-4">
                            <Input
                                name="rest"
                                title="Recupero (s)"
                                type="number"
                                required
                                min="0"
                                placeholder="90"
                                value={config.rest}
                                onInput={(e) => set('rest', parseInt(e.target.value) || 0)}
                                error={errors.rest}
                            />
                        </div>
                    </div>

                    <div className="section-label">Parametri avanzati</div>
                    <div className="row g-2 mb-3">
                        <div className="col-6">
                            <Input
                                name="load"
                                title="Peso"
                                type="text"
                                placeholder="es. 80kg"
                                value={config.load || ''}
                                onInput={(e) => set('load', e.target.value)}
                                disabled
                                error={errors.load}
                            />
                        </div>
                        <div className="col-3">
                            <Input
                                name="rpe"
                                title="RPE"
                                type="number"
                                min="1"
                                max="10"
                                placeholder="—"
                                value={config.rpe || ''}
                                onInput={(e) => set('rpe', e.target.value ? parseInt(e.target.value) : undefined)}
                                disabled
                                error={errors.rpe}
                            />
                        </div>
                        <div className="col-3">
                            <Input
                                name="rir"
                                title="RIR"
                                type="number"
                                min="0"
                                max="10"
                                placeholder="—"
                                value={config.rir || ''}
                                onInput={(e) => set('rir', e.target.value ? parseInt(e.target.value) : undefined)}
                                disabled
                                error={errors.rir}
                            />
                        </div>
                    </div>

                    <Textarea
                        name="notes"
                        title="Note esercizio"
                        placeholder="Indicazioni tecniche, note..."
                        value={config.notes || ''}
                        onInput={(e) => set('notes', e.target.value)}
                        error={errors.notes}
                    />
                </form>

                <div className="config-panel__footer">
                    <button type="button" className="btn btn-outline-secondary" onClick={onClose}>
                        Annulla
                    </button>
                    <button type="submit" form="exercise-config-form" className="btn btn-primary">
                        Aggiungi
                    </button>
                </div>
            </div>
        </div>
    );
}

export default ExerciseConfigPanel;
