import React from 'react';
import { Button, Card } from 'react-bootstrap';
import { Input, Select } from './FormComponents';
import { formatDate } from '../utils/date';
import { getUserInitials, getUserName } from '../functions';

const InfoItem = ({ label, children }) => (
    <div className="profile-page__info-item">
        <label>{label}</label>
        <p>{children || '-'}</p>
    </div>
);

const FormField = ({ children }) => (
    <div className="profile-page__form-item">{children}</div>
);

const SESSO_LABELS = { M: 'Maschio', F: 'Femmina' };

/**
 * Card anagrafica utente con supporto per modalità view e edit.
 *
 * View-only (default): passa solo `user`.
 * Editing abilitato: passa anche `isEditing`, `onEdit`, `onSave`, `onCancelEdit`,
 *   `onInputChange`, `errors`. Il form viene mostrato solo se `isEditing=true`.
 * Avatar upload: passa `avatarPreview` e `onAvatarChange`.
 * Reload: passa `onReload`.
 *
 * Nessuna prop opzionale → puramente read-only (AthleteDetail).
 */
const UserProfileCard = ({
    user,
    isEditing = false,
    avatarPreview,
    onAvatarChange,
    onReload,
    onEdit,
    onSave,
    onCancelEdit,
    onInputChange,
    errors = {},
    loading = false,
}) => {
    const displayAvatar = avatarPreview || user?.avatar_url;
    const canEdit = !!onSave;

    return (
        <Card className="profile-page__card profile-page__card--primary mb-4">
            <Card.Body className="position-relative">

                {/* Avatar + nome/email — sempre visibile */}
                <div className="profile-page__avatar-section">
                    <div className="profile-page__avatar-wrapper">
                        {displayAvatar ? (
                            <img src={displayAvatar} alt="Avatar" className="profile-page__avatar" />
                        ) : (
                            <div className="profile-page__avatar-placeholder">
                                {getUserInitials(user)}
                            </div>
                        )}
                        {onAvatarChange && (
                            <label className="profile-page__avatar-upload">
                                <input
                                    type="file"
                                    accept="image/*"
                                    onChange={onAvatarChange}
                                    style={{ display: 'none' }}
                                />
                                <i className="fas fa-camera"></i>
                            </label>
                        )}
                    </div>
                    <div className="profile-page__avatar-info">
                        <h3 className="profile-page__avatar-name">{getUserName(user)}</h3>
                        <p className="profile-page__avatar-email">{user?.email}</p>
                    </div>
                </div>

                {/* Reload button */}
                {onReload && (
                    <Button
                        variant="outline-primary"
                        onClick={onReload}
                        disabled={loading}
                        size="sm"
                        className="position-absolute top-0 end-0 m-4"
                    >
                        <i className={`fa${loading ? ' fa-spinner fa-spin' : 's fa-sync-alt'}`}></i>
                    </Button>
                )}

                <div className="profile-page__form-section">
                    {!isEditing ? (
                        /* ── Modalità visualizzazione ── */
                        <>
                            <div className="profile-page__info-grid">
                                <InfoItem label="Username">{user?.username}</InfoItem>
                                <InfoItem label="Email">{user?.email}</InfoItem>
                                <InfoItem label="Nome">{user?.nome}</InfoItem>
                                <InfoItem label="Cognome">{user?.cognome}</InfoItem>
                                <InfoItem label="Cellulare">{user?.cellulare}</InfoItem>
                                <InfoItem label="Data di nascita">
                                    {user?.data_nascita ? formatDate(user.data_nascita, 'long') : null}
                                </InfoItem>
                                <InfoItem label="Sesso">{SESSO_LABELS[user?.sesso]}</InfoItem>
                            </div>

                            {canEdit && onEdit && (
                                <div className="profile-page__actions">
                                    <Button variant="primary" onClick={onEdit}>
                                        <i className="fas fa-edit me-2"></i>
                                        Modifica profilo
                                    </Button>
                                </div>
                            )}
                        </>
                    ) : (
                        /* ── Modalità editing ── */
                        <form onSubmit={onSave}>
                            <div className="profile-page__form-grid">
                                <FormField>
                                    <Input required name="username" title="Username"
                                        value={user?.username || ''} onInput={onInputChange} error={errors.username} />
                                </FormField>
                                <FormField>
                                    <Input required name="email" title="Email" type="email"
                                        value={user?.email || ''} onInput={onInputChange} error={errors.email} />
                                </FormField>
                                <FormField>
                                    <Input name="nome" title="Nome"
                                        value={user?.nome || ''} onInput={onInputChange} error={errors.nome} />
                                </FormField>
                                <FormField>
                                    <Input name="cognome" title="Cognome"
                                        value={user?.cognome || ''} onInput={onInputChange} error={errors.cognome} />
                                </FormField>
                                <FormField>
                                    <Input name="cellulare" title="Cellulare" type="tel"
                                        value={user?.cellulare || ''} onInput={onInputChange} error={errors.cellulare} />
                                </FormField>
                                <FormField>
                                    <Input name="data_nascita" title="Data di nascita" type="date"
                                        value={user?.data_nascita ? user.data_nascita.split('T')[0] : ''}
                                        onInput={onInputChange} error={errors.data_nascita} />
                                </FormField>
                                <FormField>
                                    <Select name="sesso" title="Sesso"
                                        value={user?.sesso || ''} onInput={onInputChange} error={errors.sesso}
                                        options={[{ name: 'Maschio', value: 'M' }, { name: 'Femmina', value: 'F' }]} />
                                </FormField>
                            </div>
                            <div className="profile-page__form-actions flex-column flex-md-row">
                                <Button type="button" variant="outline-primary" onClick={onCancelEdit} disabled={loading}>
                                    Annulla
                                </Button>
                                <Button type="submit" variant="primary" disabled={loading}>
                                    {loading ? (
                                        <><i className="fa fa-spinner fa-spin me-2"></i><span>Salvataggio in corso</span></>
                                    ) : (
                                        <><i className="fas fa-save me-2"></i><span>Salva modifiche</span></>
                                    )}
                                </Button>
                            </div>
                        </form>
                    )}
                </div>
            </Card.Body>
        </Card>
    );
};

export default UserProfileCard;
