import { useDispatch, useSelector } from 'react-redux';
import { selectCurrentStep, setStep } from '../../features/workoutBuilder/workoutBuilderSlice';

const STEP_LABELS = ['Informazioni', 'Esercizi', 'Riepilogo'];

function WizardNavigation({ onCancel, canProceed, isLastStep, onFinish, saving }) {
    const dispatch = useDispatch();
    const currentStep = useSelector(selectCurrentStep);

    return (
        <div className="wizard-nav">
            <div className="wizard-steps">
                {STEP_LABELS.map((label, idx) => (
                    <div
                        key={idx}
                        className={`wizard-step-indicator${idx === currentStep ? ' active' : ''}${idx < currentStep ? ' done' : ''}`}
                    >
                        <span className="wizard-step-indicator__num">{idx + 1}</span>
                        <span className="wizard-step-indicator__label">{label}</span>
                    </div>
                ))}
            </div>

            <div className="wizard-nav__actions">
                {currentStep > 0 ? (
                    <button
                        className="btn btn-outline-secondary"
                        onClick={() => dispatch(setStep(currentStep - 1))}
                        disabled={saving}
                    >
                        <i className="fa-solid fa-chevron-left me-1"></i>
                        Indietro
                    </button>
                ) : (
                    <button className="btn btn-outline-secondary" onClick={onCancel} disabled={saving}>
                        Annulla
                    </button>
                )}

                {isLastStep ? (
                    <button
                        className="btn btn-primary"
                        onClick={onFinish}
                        disabled={saving || !canProceed}
                    >
                        {saving ? (
                            <span className="spinner-border spinner-border-sm me-2" role="status" />
                        ) : (
                            <i className="fa-solid fa-floppy-disk me-2"></i>
                        )}
                        Salva Programma
                    </button>
                ) : (
                    <button
                        className="btn btn-primary"
                        onClick={() => dispatch(setStep(currentStep + 1))}
                        disabled={!canProceed}
                    >
                        Avanti
                        <i className="fa-solid fa-chevron-right ms-1"></i>
                    </button>
                )}
            </div>
        </div>
    );
}

export default WizardNavigation;
