import React, { useRef, useEffect } from 'react';

const TOOLS = [
    { cmd: 'bold', icon: 'fa-bold', title: 'Grassetto' },
    { cmd: 'italic', icon: 'fa-italic', title: 'Corsivo' },
    { cmd: 'underline', icon: 'fa-underline', title: 'Sottolineato' },
    { cmd: 'strikeThrough', icon: 'fa-strikethrough', title: 'Barrato' },
    { cmd: '|' },
    { cmd: 'insertUnorderedList', icon: 'fa-list-ul', title: 'Lista puntata' },
    { cmd: 'insertOrderedList', icon: 'fa-list-ol', title: 'Lista numerata' },
];

function RichTextEditor({ value, onChange, placeholder = 'Descrizione' }) {
    const editorRef = useRef(null);

    // Imposta il contenuto iniziale una sola volta senza toccare il DOM in seguito
    useEffect(() => {
        if (editorRef.current && editorRef.current.innerHTML !== value) {
            editorRef.current.innerHTML = value ?? '';
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const exec = (cmd) => {
        editorRef.current?.focus();
        document.execCommand(cmd, false, null);
        onChange(editorRef.current?.innerHTML ?? '');
    };

    return (
        <div className="rte">
            <div className="rte__toolbar">
                {TOOLS.map((t, i) =>
                    t.cmd === '|' ? (
                        <div key={i} className="rte__sep" />
                    ) : (
                        <button
                            key={t.cmd}
                            type="button"
                            title={t.title}
                            className="rte__btn"
                            onMouseDown={(e) => { e.preventDefault(); exec(t.cmd); }}
                        >
                            <i className={`fa-solid ${t.icon}`}></i>
                        </button>
                    )
                )}
            </div>
            <div
                ref={editorRef}
                className="rte__body"
                contentEditable
                suppressContentEditableWarning
                onInput={() => onChange(editorRef.current?.innerHTML ?? '')}
                data-placeholder={placeholder}
            />
        </div>
    );
}

export default RichTextEditor;
