import { useDispatch, useSelector } from 'react-redux';
import {
    updateMetadata,
    selectMetadata,
    selectWorkoutOptions,
} from '../../features/workoutBuilder/workoutBuilderSlice';
import { Input, InputError, Select } from '../FormComponents';
import RichTextEditor from '../RichTextEditor';
import ToggleRow from '../ToggleRow';

function StepMetadata({ fieldErrors = {} }) {
    const dispatch = useDispatch();
    const metadata = useSelector(selectMetadata);
    const { levels, training_types, objectives } = useSelector(selectWorkoutOptions);
    const set = (field, value) => dispatch(updateMetadata({ [field]: value }));

    const handleTemplateToggle = (checked) => {
        const updates = { isTemplate: checked };
        if (checked) {
            updates.isGlobalTemplate = false;
            updates.objective = '';
            updates.expiry = '';
        }
        dispatch(updateMetadata(updates));
    };

    return (
        <>
            <h4 className="wizard-step-title">Informazioni Programma</h4>

            <div className="wizard-step-content">
                <Input
                    name="title"
                    title="Nome Programma"
                    required
                    placeholder="Nome del programma..."
                    value={metadata.title}
                    onInput={(e) => set('title', e.target.value)}
                    error={fieldErrors.title}
                />

                <div className="row g-3 mt-1">
                    <div className="col-sm-6">
                        <Select
                            name="level"
                            title="Livello"
                            required
                            options={levels}
                            value={metadata.level}
                            onInput={(e) => set('level', e.target.value)}
                            error={fieldErrors.level}
                        />
                    </div>
                    <div className="col-sm-6">
                        <Select
                            name="type"
                            title="Tipologia"
                            required
                            options={training_types}
                            value={metadata.type}
                            onInput={(e) => set('type', e.target.value)}
                            error={fieldErrors.training_type}
                        />
                    </div>
                </div>

                <div className="row g-3 mt-0">
                    <div className="col-sm-6">
                        <Select
                            name="objective"
                            title="Obiettivo"
                            required
                            options={objectives}
                            value={metadata.objective}
                            onInput={(e) => set('objective', e.target.value)}
                            disabled={metadata.isTemplate}
                            error={fieldErrors.objective}
                        />
                    </div>
                    <div className="col-sm-6">
                        <Input
                            name="expiry"
                            title="Scadenza"
                            required
                            type="date"
                            value={metadata.expiry}
                            onInput={(e) => set('expiry', e.target.value)}
                            disabled={metadata.isTemplate}
                            error={fieldErrors.expiry}
                        />
                    </div>
                </div>

                <div className="form-group-wp mt-3">
                    <label className="form-group-label">Descrizione</label>
                    <RichTextEditor
                        value={metadata.description}
                        onChange={(html) => set('description', html)}
                        placeholder="Obiettivi, note generali..."
                    />
                    <InputError error={fieldErrors.description} className="d-block" />
                </div>

                <ToggleRow
                    id="is-template-switch"
                    label="Crea come modello"
                    tooltip="I modelli possono essere riutilizzati come punto di partenza per nuovi programmi, senza modificare l'originale."
                    checked={metadata.isTemplate}
                    onChange={(e) => handleTemplateToggle(e.target.checked)}
                    className="mt-3"
                />

                {metadata.isTemplate && (
                    <ToggleRow
                        id="is-global-template-switch"
                        label="Modello globale"
                        tooltip="I modelli globali sono visibili a tutti gli utenti della piattaforma. I modelli privati sono visibili solo a te."
                        checked={metadata.isGlobalTemplate}
                        onChange={(e) => set('isGlobalTemplate', e.target.checked)}
                        className="mt-2"
                    />
                )}
            </div>
        </>
    );
}

export default StepMetadata;
